Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777192783,to_date('12-MAY-23','DD-MON-RR'),'CBCV',to_date('01-JAN-70','DD-MON-RR'),'Isobel Mackenzie advises seniors to be mindful and take health precautions during this weekend''s heat wave. The seniors advocate is particularly concerned about seniors living alone in older apartment buildings with a lot of glass windows and no air conditioning. [env, hlth, zza, pssg]','Mackenzie - heat wave precautions','Talk Radio',0,1,0,null,to_date('12-MAY-23','DD-MON-RR'),to_date('12-MAY-23','DD-MON-RR'),null,null,null,'column','CBC On the Island','CBC On the Island',null,null,null,402,1800,null,to_date('01-JAN-70','DD-MON-RR'),'777192783.m4a','2023/05/12/777192783.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'rknapman',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777196437,to_date('12-MAY-23','DD-MON-RR'),'CBU',to_date('01-JAN-70','DD-MON-RR'),'Meera Bains points out concerns over BC Housing and Atira span several housing ministers and provincial governments. The CBC legislative reporter notes current Housing Minister Ravi Kahlon has ordered a review of Atira''s funding. On another topic, Justine Hunter says Adrian Dix is reminding people this weekend''s heat wave could pose a risk to people and to take precautions. The Globe and Mail reporter adds many areas are still waiting for federal funding to address issues related to previous floods. Also discussed: Harry Lali. [env, forr, pssg, zpz, hozz, hlth]','Bains/Hunter - BC politics','Talk Radio',0,1,0,null,to_date('12-MAY-23','DD-MON-RR'),to_date('12-MAY-23','DD-MON-RR'),null,null,null,'column','CBC Early Edition','CBC Early Edition',null,null,null,630,2880,null,to_date('01-JAN-70','DD-MON-RR'),'777196437.m4a','2023/05/12/777196437.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'jmartyn',0,0,0,null,0,0,0,0,null,null,null);
