Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778830159,to_date('23-MAY-23','DD-MON-RR'),'CP News',to_date('23-MAY-23','DD-MON-RR'),null,'(BBN-Milwaukee-Stax)','CP News',0,0,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,null,null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2108210762/_k/Vs4jN46ra5tYJKKA',0,null,0,0,null,0,0,0,0,'rss',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778151003,to_date('18-MAY-23','DD-MON-RR'),'The Tyee',to_date('01-JAN-70','DD-MON-RR'),'It has been one of the worst starts to Alberta''s wildfire season in decades with thousands of people displaced, sometimes with only hours notice, and homes, businesses and hundreds of thousands of hectares burned.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'There is no question of a direct connection between human-induced global warming and the wildfires, an expert said. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'But despite the mounting human and financial cost, two weeks into Alberta''s provincial election, the United Conservative Party and the New Democrats have essentially ignored the issue of human-induced global warming and Alberta''s duty to address it.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Climate change is not something that works particularly well as a priority election issue," said Lori Williams, an associate professor of policy studies at Calgary''s Mount Royal University. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"The top two issues in Alberta are affordability and health care. And leadership after that." ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Both of Alberta''s main political parties claim they balance economic and environmental policies. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"It is just always a delicate balance to talk about energy and the environment," she said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"As much as the wildfires are a huge problem for some people in Alberta," Williams said, "the solution to that problem is not in long-term climate policy, it is disaster management, emergency response and leadership."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Keith Stewart of Greenpeace Canada wonders how balanced this "delicate balance" is when residents across the province couldn''t safely breathe the air earlier this week due to wildfire smoke.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'So far this wildfire season, there have been 475 fires with over 615,000 hectares burned. About 16,000 people have been forced to flee, including the residents of entire towns in northern Alberta. Dozens of homes and businesses have been razed, many in Indigenous or M鴩s settlements. Provincial disaster authorities say, as of Tuesday, there were 89 active fires, 28 of those were out of control. ','As Alberta burns, politicians ''dare not speak'' of climate change','Internet',0,0,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,null,0,'krypto',0,0,null,0,0,0,0,'chall',0,0,0,null,0,0,0,0,null,null,null);
