Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778159021,to_date('18-MAY-23','DD-MON-RR'),'CIVT',to_date('01-JAN-70','DD-MON-RR'),'Kimiko Hirakida wants everyone to be alert and aware when they''re around the water. The Lifesaving Society of BC & Yukon program manager points out drowning is the leading cause of death for children ages one to four. Hirakida also warns against swimming in open water during the spring snowmelt. [pssg]','Hirakida - water safety','TV News',0,1,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,'column','CTV Morning Live','CTV Morning Live',null,null,null,255,300,null,to_date('01-JAN-70','DD-MON-RR'),'778159021.mp4','2023/05/18/778159021.mp4',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'rfreeman',0,0,0,null,0,0,0,0,null,null,null);
