Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777895715,to_date('17-MAY-23','DD-MON-RR'),'CHAN',to_date('01-JAN-70','DD-MON-RR'),'Emily Lazatin reports residents of Fort St John remain on evacuation alert as wildfires continue to burn in the area. The Global reporter says firefighters were given a bit of a reprieve yesterday when winds blew the fires away from the city, but conditions are still dry and hot. Cliff Chapman of BCWFS says the amount of rain which falls in June will play a crucial role in the rest of wildfire season. [embc, forr, pssg, env, maz]','Lazatin/Chapman - northeast BC wildfires','TV News',1,1,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,null,'column','Global BC Morning News','Global BC Morning News',null,null,null,109,300,null,to_date('01-JAN-70','DD-MON-RR'),'777895715.mp4','2023/05/17/777895715.mp4',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'oscott',0,0,0,null,0,0,0,0,null,null,null);
