Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777618539,to_date('15-MAY-23','DD-MON-RR'),'CBTK',to_date('01-JAN-70','DD-MON-RR'),'Kent Moore is concerned that the warm, dry conditions which have sparked wildfires in northern BC and Alberta will likely persist for the next few weeks. The University of Toronto climate scientist thinks the wildfires are so large officials will likely have to let them run their course. Moore adds climate change is leading to warmer temperatures, which lead to more wildfires. [env, embc, forr, pssg]','Moore - BC/Alberta wildfires','Talk Radio',0,1,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),null,null,null,'column','CBC Daybreak South','CBC Daybreak South',null,null,null,481,600,null,to_date('01-JAN-70','DD-MON-RR'),'777618539.m4a','2023/05/15/777618539.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'rfreeman',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777386770,to_date('14-MAY-23','DD-MON-RR'),'Times Colonist (Victoria)',to_date('01-JAN-70','DD-MON-RR'),'Education of both Indigenous and non-Indigenous students has a key role to play in long-term reconciliation' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'In B.C.''s public schools, the graduation rate for ­Indigenous students is on the rise - 72% of Indigenous students completed high school in 2020-21, up from 66.2% in the 2016-17 school year.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'That''s good news. But an April report from non-partisan People for Education organization executive director Annie Kidder outlines some steps that still need to be taken to expand upon and consolidate this success.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The report, entitled "Still Waiting For Truth and ­Reconciliation," focuses primarily on the fact that while it has been eight years since the Truth and ­Reconciliation Commission issued its calls to action, the 13 that specifically address children and youth have not been fully implemented as yet. And none are actually focused on education.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'This according to an analysis by the Yellowhead Institute, an Indigenous-led research and education centre based in the faculty of arts at Toronto ­Metropolitan University.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Kidder''s report is not an exercise in fault finding and emphasizes instead the kind of thing Murray ­Sinclair, chair of the Truth and Reconciliation Commission, was talking about when he said "education has a key role to play in long-term reconciliation, and changes in our education systems must include improvements in the education of both Indigenous and non-Indigenous ­students."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'In his preface to the Truth and Reconciliation Call For Action, Sinclair went on to say: "Education is what got us into this mess. We need to look at the way we are educating children. That''s why we say that this is not an Aboriginal problem. It''s a Canadian problem."','Calls to action on Indigenous education also benefit non-Indigenous students','Newspaper',0,1,0,null,to_date('14-MAY-23','DD-MON-RR'),to_date('14-MAY-23','DD-MON-RR'),null,null,'D11','column','Geoff Johnson','Geoff Johnson',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,null,0,'krypto',0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
