Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778164629,to_date('18-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'COQUITLAM, B.C. - Mounties in Coquitlam, B.C., are asking for the public''s help identifying a suspect who they say keyed about 400 vehicles at a car dealership in the city. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police say that between January and April, they received three separate reports of alleged "mass car ''keying'' incidents" at the Journey Chrysler dealership. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'They released video footage of the suspect dragging a sharp object across the outside of the vehicles, scratching their paint. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police say it resulted in estimated $500,000 in damage. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'They have identified the suspect in the video as a white woman between 40 and 50 years old, with shoulder-length blond hair and a "heavy build." ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police say she is believed to drive a Ford Escape and are asking anyone who may have witnessed the incident or recognize the suspect to come forward. 
