Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (779226155,to_date('25-MAY-23','DD-MON-RR'),'CKNW',to_date('01-JAN-70','DD-MON-RR'),'Vaughn Palmer reports the fallout from the province''s decision to send cancer patients to Bellingham for radiation treatment is becoming a source of frustration for BC cancer patients who have had to cover their own costs for travel to treatment centres. The Vancouver Sun columnist also digs into the bureaucratic communications issue in health care after Dr Urbain Ip raises the alarm about overcrowding at Surrey Memorial, saying in spite of Adrian Dix''s protestations to the contrary, health care workers do face repercussions for speaking out. [zpz, hlth]','Palmer - US cancer treatment BC','Talk Radio',0,1,0,null,to_date('25-MAY-23','DD-MON-RR'),to_date('25-MAY-23','DD-MON-RR'),null,null,null,'column','CKNW View From Victoria','CKNW View From Victoria',null,null,null,14,2700,null,to_date('01-JAN-70','DD-MON-RR'),'779226155.m4a','2023/05/25/779226155.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'tday',0,0,0,null,0,0,0,0,'not applicable',null,null);
