Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778822093,to_date('23-MAY-23','DD-MON-RR'),'National Post',to_date('01-JAN-70','DD-MON-RR'),'While future platforms and local candidates will play a role in the next federal election, anyone who thinks large portions of the electorate cast their vote based on little more than vibes is kidding themselves. Often, vibes decide elections - in particular, the vibes of party l','Poilievre has the edge on Trudeau','Newspaper',0,1,0,null,to_date('22-MAY-23','DD-MON-RR'),to_date('22-MAY-23','DD-MON-RR'),'National','Issues','A06',null,null,'Sabrina Maddeaux',null,null,null,0,0,null,null,null,null,null,0,'NTNP20230523050529.FMS',0,0,null,0,0,0,0,null,0,0,0,0,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778145073,to_date('18-MAY-23','DD-MON-RR'),'CBC Online',to_date('01-JAN-70','DD-MON-RR'),'<img title="The open-concept, minimalist design favoured by restaurants today may look good, but they can also be tough on the ear." src="https://i.cbc.ca/1.5349058.1684387704!/fileImage/httpImage/image.jpg_gen/derivatives/16x9_460/modern-restaurant-eating-lunch.jpg" />' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Restaurants across Canada are "in crisis" and still fighting for survival, says Restaurants Canada, a not-for-profit representing 30,000 restaurants countrywide. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'They are said to be facing a "triple whammy" of challenges: inflationary costs, labour shortages and COVID-19 loan repayments.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We''re in this post-pandemic hangover phase," said Mark von Schellwitz, vice-president of the Western Canada division. "It''s been really difficult to get back to normal."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Bankruptcy filings in food services have spiked 116 per cent since 2022, according to Restaurants Canada. It says about half of restaurants are unprofitable right now, compared to only 12 per cent before the pandemic.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Restaurants Canada says 25 per cent of members worry they won''t be able to survive another year. It''s lobbying the federal government to extend the repayment deadline for the Canada Emergency Business Account (CEBA) to give struggling businesses some reprieve.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'In B.C., the struggling restaurant sector has spent the last few weeks pressuring the provincial government for support. The group has been quietly meeting with the labour and jobs ministers, resulting in a list of 10 recommendations to the province. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'CBC News has learned the government is currently working on additional supports - not only for the restaurant sector, but for small businesses as well. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We do know that a number of small businesses are feeling the impact," said B.C. Jobs Minister Brenda Bailey, referring to the inflation and labour shortages, along with COVID-related debt.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Bailey said the government will announce shortly measures to assist restaurants and small businesses.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Changing business model to survive','''Post-pandemic hangover'' forces many restaurants to file for bankruptcy: Restaurants Canada','Internet',1,1,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,'SyndCategoryImpl.taxonomyUri=null SyndCategoryImpl.name=News/Canada/British Columbia ','CBC Online','CBC Online',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.cbc.ca/news/canada/british-columbia/post-pandemic-restaurants-bankrupt-1.6847327?cmp=rss',0,null,0,0,null,0,0,0,0,'rfreeman',0,0,0,null,0,0,0,0,null,null,null);
