Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778530594,to_date('21-MAY-23','DD-MON-RR'),'Global News: BC 1',to_date('01-JAN-70','DD-MON-RR'),'Massive flames were seen Saturday evening in the Comox Valley on Vancouver Island as a gas station burned down.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The fully engulfed gas station was caught on video by a bystander.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The fire ignited sometime around 7 p.m. at an Esso station on Anderton Road, and was first reported as a car fire, which quickly turned into a structure fire, firefighters said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"The incident escalated very quickly and upon arrival everything was on fire essentially," said Brent Craven, a Comox Fire Rescue firefighter.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"(There were) large amounts of fuel at the rear of the building, and we had propane tanks that were our major concern at the time."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Two people were taken to hospital with minor injuries and neighbouring residents were also temporarily evacuated.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We heard a crash out here and then soon as I came outside we heard another smaller explosion at that point," said Shirley Mcquillan, who lives about a block away.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"It was pretty scary because you''re dealing with explosives, propane or gas, and not knowing exactly what was on fire at first."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Around 40 firefighters responded to the blaze and the cause of the fire is under investigation. [pssg, empr]','Comox Valley gas station goes up in flames, caught on video','Internet',1,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Darrian Matassa-Fung','Darrian Matassa-Fung',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://globalnews.ca/news/9714337/comox-valley-gas-station-fire-video/',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
