Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778164895,to_date('18-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'Nova Scotia Premier Tim Houston has announced the construction of a new school for francophone students on the province''s Eastern Shore. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The new school, to be completed by September 2027, will replace Ecole des Beaux-Marais, which was built in 1950 and currently serves the area from Lake Echo to Ship Harbour. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Houston issued a statement saying the Education Department will work with the community to design the school and choose its location. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The school will be part of the Conseil scolaire acadien provincial and serve students from pre-primary to Grade 8. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Department of Public Works will issue a tender for the design once the site selection process has been completed. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Marcel Cottreau, president of the Conseil scolaire acadien provincial, said the new school will offer students a rich, high-quality educational experience in a new, modern building.','Nova Scotia premier announces plan to build new school for francophone students','CP News',1,1,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2107406880/_k/wjC12l3xVkSd5JFR',0,null,0,0,null,0,0,0,0,'chall',0,0,0,null,0,0,0,0,null,null,null);
