Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778508989,to_date('21-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'A wildfire has broken out southwest of Apex between Apex and Hedley in the Cahill Creek area.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The BC Wildfire Service website says the fire was discovered just before 5:20 p.m. Saturday and that the size of the blaze is currently unknown.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Right now, the wildfire is considered to be out of control and the suspected cause is under investigation.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Currently, there is no evacuation orders or alerts associated with this incident.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Castanet will update the story when more information becomes available. [forr, embc, pssg]','Wildfire breaks out near Apex, Hedley','Internet',1,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=48507' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/screen_shot_2023-05-20_at_7.52.47_pm_p3688385.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kelowna/427867/Wildfire-breaks-out-near-Apex-Hedley',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778508983,to_date('21-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'The City of West Kelowna can finally close the book on damage caused by flooding in 2017.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The city has received $227,000 from the provincial Disaster Financial Assistance Program to complete damage repair to Rock Ridge Park that was caused during the historic floods of 2017.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'According to a staff report, an unnamed drainage channel flows through a forested area through Rock Ridge Park and across four private properties.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"High flows during the 2017 freshet event dislodged material from the bed and banks throughout the channel and blocked two stormwater culvert crossings," the report states.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Recovery works restored the function of two blocked stormwater culvert crossings prior to the 2018 freshet.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"The close out report included a hazard assessment that highlighted a residual risk of flooding downstream from a failure of the unstable channel banks that was not addressed with the first phase of recovery works."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The report says recovery work to construct and stabilize the affected portion of the degraded channel bed and banks was added to the city''s 2017 flood recovery plan.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The city share of the project is estimated at $303,000.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Flooding in 2017 resulted in 32 separate recovery projects on Smith, McDougall and Powers creeks and another 18 on the shores of Okanagan Lake.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Rock Ridge Park project is the only outstanding project remaining from the flooding event.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Staff recommend the contract be awarded to Cabin Resources Management. [forr, embc, pssg, env, maz]','West Kelowna has received funds to complete 2017 flood recovery work','Internet',1,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=159949' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/bank._p3688148.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/West-Kelowna/427702/West-Kelowna-has-received-funds-to-complete-2017-flood-recovery-work',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778508988,to_date('21-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'The City of West Kelowna wants to hear your thoughts on its parks and recreational trails.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The city wants your input to help decide how to invest in the parks and recreational trail systems for the next five years and beyond.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Residents are invited to take a look online anytime until June 23.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Visit OurWK.ca to check out the project pages and view the display boards.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Residents can also stop by Municipal Hall at 2760 Cameron Road to pick up an engagement toolkit.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The community input will help inform draft recommendations for the Parks Master Plan and the Rec Trails Master Plan.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'In the Fall, draft plans will be shared with the community for review during the second round of engagement. [maz, env, forr]','West Kelowna seeking feedback on parks and trails','Internet',1,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=76164' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/parks_and_rec_graphic_p3687362.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/West-Kelowna/427321/West-Kelowna-seeking-feedback-on-parks-and-trails',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
