Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778425752,to_date('20-MAY-23','DD-MON-RR'),'CBYG',to_date('01-JAN-70','DD-MON-RR'),'Chrystia Freeland is confident a deal will be reached between the federal government, Ontario and Stellantis to get the battery plant built. The federal Finance minister defends the need for the Stellantis battery plant, saying Canada needs to invest heavily in the clean economy. Also discussed: Canada''s sanctions on Russia. [env, empr, fin]','Freeland - Stellantis battery plant','Talk Radio',0,1,0,null,to_date('20-MAY-23','DD-MON-RR'),to_date('20-MAY-23','DD-MON-RR'),null,null,null,'column','CBC The House','CBC The House',null,null,null,648,420,null,to_date('01-JAN-70','DD-MON-RR'),'778425752.m4a','2023/05/20/778425752.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778841002,to_date('23-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'Kamloops Coun. Nancy Bepple is running for director on the Federation of Canadian Municipalities board.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Nancy Bepple, a Kamloops councillor, is hoping to bring regional representation to the Federation of Canadian Municipalities board of directors.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Bepple attended a Thompson-Nicola Regional District meeting as an alternate director on Thursday, and announced her intentions to the board.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"I''m the only one running as a director [from] here north to the top of B.C., so it would be great to have a representative from the Interior on the board," Bepple said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Bepple will be representing Kamloops at the FCM conference, which will be held in Toronto from May 25 to 28. She will be accompanied by a few other local elected officials, including Cache Creek Mayor John Ranta and Usoff Tsao, director for TNRD Electoral Area A.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Bepple received support for her nomination from Kamloops mayor and councillors during a May 9 council meeting.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"I think you would do a fantastic job representing the city, whether you get on as a director or an appointment to a committee," said Coun. Mike O''Reilly.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Bepple said she ran unsuccessfully for a director role in the past, but served as an FCM committee member from 2012 until 2014.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'According to FCM, the federation includes representatives from more than 2,100 municipalities located across Canada. The group conducts advocacy work to ensure citizens'' needs are reflected in federal government policy. [maz]','Kamloops councillor aims to represent the region on FCM board of directors','Internet',1,1,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=65387' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/headshot_3_campaign_photo_p3617039_p3688285.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kamloops/427802/Kamloops-councillor-aims-to-represent-the-region-on-FCM-board-of-directors',0,null,0,0,null,0,0,0,0,'jglass',0,0,0,null,0,0,0,0,null,null,null);
