Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777883250,to_date('16-MAY-23','DD-MON-RR'),'Kamloops This Week',to_date('01-JAN-70','DD-MON-RR'),'Ahead of the Victoria Day long weekend, the BC Wildfire Service is warning that the current dry and hot conditions are creating an environment ripe for fire -- even in the southern half of the province.  Director of wildfire operations Cliff Chapman provided an update to media out','Wildfire warning for Victoria Day long weekend','Newspaper',0,0,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,null,null,null,'Sean Brady',null,null,null,0,0,null,null,null,null,null,0,'APKW20230516100542.FMS',0,0,null,0,0,0,0,null,0,0,0,0,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777912309,to_date('17-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'A judge has issued a $15-million settlement to a 24-year-old Abbotsford man for catastrophic injuries he suffered in a car accident caused by a drunk driver on March 30, 2008, at the age of nine.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Arshdeep Singh Sidhu, now a ventilator-dependent quadriplegic, is to receive $13 million for future care from the Insurance Corporation of B.C., following prolonged and complex legal proceedings.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Sidhu had been a passenger as his parents drove through an intersection when drunk driver Jan Abram Hiebert ran a stop sign, crashing into the family. Hiebert''s blood alcohol level was three times the legal limit, according to court documents.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Hiebert smashed into the driver''s side of the family''s Nissan Pathfinder, where Sidhu sat in the backseat, and it had been alleged that at the time of the collision, the shoulder seat belt rested improperly on Sidhu''s right shoulder, not left, which caused a near complete spinal cord transection.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Sidhu brought a claim against Nissan, which reached a settlement with Sidhu prior to Justice Carla Forth''s May 12 ruling. Sidhu, represented by Michael Slater K.C. and Sam Jaworski of Slater Vecchio LLP, claimed Nissan failed to include rear seat belt pretensioners and knew or ought to have known seatbelts would be misused by children. The settlement was not made public by the judge.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Sidhu put Nissan''s settlement in a trust fund and continued to receive just over $20,000 from the Choices in Supports for Independent Living (CSIL) program, which funds disabled individuals. The trust "is a discretionary, irrevocable trust, meaning the plaintiff cannot compel the trustees to pay money to him, or on his behalf," noted the ruling.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Sidhu started CSIL when he turned 19; initially, he received funding based on 420 hours per month, which was the Ministry of Health guideline in place at the time. His family advocated to get 611 hours per month, which still did not cover the time spent by Sidhu''s father caring for his son.','BC man granted $15m settlement after drunk driver paralyzed him','Internet',1,1,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=66118' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/icbc-robkruyt._p3530734_p3687099.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/BC/427189/B-C-man-granted-15M-settlement-after-drunk-driver-paralyzed-him',0,null,0,0,null,0,0,0,0,'artapia',0,0,0,null,0,0,0,0,null,null,null);
