Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777621387,to_date('15-MAY-23','DD-MON-RR'),'CFAX',to_date('01-JAN-70','DD-MON-RR'),'Vibert Jack outlines a Supreme Court of Canada case challenging the extent to which media is restricted on reporting the details about jury trials. The BC Civil Liberties Association litigation director acknowledges that publication bans are sometimes necessary but asserts that public scrutiny of the justice system is vital in a democracy. [mjag]','Jack - trial reporting','Talk Radio',0,1,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),null,null,null,'column','CFAX Mornings with Al Ferraby','CFAX Mornings with Al Ferraby',null,null,null,510,360,null,to_date('01-JAN-70','DD-MON-RR'),'777621387.m4a','2023/05/15/777621387.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'rdrain',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777623089,to_date('15-MAY-23','DD-MON-RR'),'BiV',to_date('01-JAN-70','DD-MON-RR'),'The Vancouver Fraser Port Authority''s (VFPA) planned Roberts Bank Terminal 2 (RBT2) project still must clear the provincial environmental approval process.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The B.C. Environmental Assessment Office (EAO) has opened a public comment period on the project''s draft assessment materials. The comment period closes on June 8.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"The assessment was carried out through a federally appointed panel. Both levels of government use this assessment, along with additional information requests and consultation with Indigenous Nations, to base their decisions about whether or not to approve the project to proceed. The federal government recently made a decision to approve the project, but it also requires provincial approval," the EAO explains.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"The Environmental Assessment Office (EAO) has principally relied on the federal panel''s findings to develop materials to support provincial ministers in making their own independent decision on if the project is in the best interests of British Columbia."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The EAO says it is seeking feedback on the drafts of the materials before sending them to provincial ministers for a decision.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'After a lengthy and complex process that started even before the port formally submitted its application a decade ago, the federal government last month gave the green light for a new three-berth container terminal adjacent to the current port facility at Roberts Bank in Delta.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The approval comes with a lengthy list of conditions.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Built on a new man-made island adjacent to the current Deltaport container facility, RBT2 would provide a 50 per cent increase to the port''s container capacity, providing 2.4 million TEUs (20-foot-equivalent units) of additional capacity annually.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The project still requires other approvals.','Deltaport expansion now going through next approval process','Internet',1,1,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),null,null,null,'column','Sandor Gyarmati, Delta Optimist','Sandor Gyarmati, Delta Optimist',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://biv.com/article/2023/05/deltaport-expansion-now-going-through-next-approval-process',0,null,0,0,null,0,0,0,0,'rdrain',0,0,0,null,0,0,0,0,null,null,null);
