Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777615396,to_date('15-MAY-23','DD-MON-RR'),'CKNW',to_date('01-JAN-70','DD-MON-RR'),'Michel Juneau-Katsuya is hopeful that MPs speaking openly about foreign interference from the Chinese government will help prevent future incidents, but he asserts that CSIS and the RCMP are not equipped to deal with it. The Nest of Spies author asserts that the issue needs to be investigated by a fully independent body that reports to the House of Commons. [mjag]','Juneau-Katsuya - foreign interference','Talk Radio',0,1,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),null,null,null,'column','CKNW Simi Sara','CKNW Simi Sara',null,null,null,604,360,null,to_date('01-JAN-70','DD-MON-RR'),'777615396.m4a','2023/05/15/777615396.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'rdrain',0,0,0,null,0,0,0,0,'not applicable',null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777616476,to_date('15-MAY-23','DD-MON-RR'),'CBCV',to_date('01-JAN-70','DD-MON-RR'),'Kent Moore is concerned that the warm, dry conditions which have sparked wildfires in northern BC and Alberta will likely persist for the next few weeks. The University of Toronto climate scientist thinks the wildfires are so large officials will likely have to let them run their course. Moore adds climate change is leading to warmer temperatures, which lead to more wildfires. [env, embc, forr, pssg]','Moore - BC/Alberta wildfires ','Talk Radio',0,1,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),null,null,null,'column','CBC On the Island','CBC On the Island',null,null,null,390,300,null,to_date('01-JAN-70','DD-MON-RR'),'777616476.m4a','2023/05/15/777616476.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'oscott',0,0,0,null,0,0,0,0,null,null,null);
