Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778150040,to_date('18-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'Campfires are still allowed throughout most of B.C., including the Thompson-Okanagan, but maybe not for long.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The first burning bans of the season take effect Thursday. Among them are bans on open burning throughout the Kamloops and Southeast fire centres.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The only part of the province under a campfire ban is the Prince George Fire Centre.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Castanet asked Cliff Chapman, the BC Wildfire Service''s director of wildfire operations, why campfires have not yet been banned throughout the Southern Interior given the region''s worsening fire danger rating.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'He said a ban could be imposed at any time - potentially even before the Victoria Day long weekend.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We assess our prohibition activity, especially when we see hazards and weather like we''re seeing right now, we assess it hourly," he said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"So that''s not to say that by the weekend we may not shift to putting a campfire ban in across the province, or looking at it next week. But right now, through our assessment, the conditions do not call for that in the south with all the variables we put into it."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'B.C. Forestry Minister Bruce Ralston said he hopes campers are careful with their fires.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"It''s very important that people take the necessary precautions when they''re using a campfire," he said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Most people have common sense, I know, so I don''t really want to lecture, but I think it''s just important that people have a heightened awareness of the fire danger."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Chapman said the fires currently burning in B.C. were not the result of unattended campfires.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Right now, we have resource capacity in the province and we''re not seeing campfires starting the fires that we''re dealing with at this point in time," he said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"So we''re trying to find that balance between allowing safe, appropriate activity in every other centre except for the northeast." [tacz, env, forr, embc, pssg, zpz]','Campfires still allowed throughout Southern Interior, but ban could come soon','Internet',1,1,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=151793' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/screen_shot_2021-06-28_at_11.40.03_am_copy_p3615550_p3687366.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kamloops/427324/Campfires-still-allowed-throughout-Southern-Interior-but-ban-could-come-soon',0,null,0,0,null,0,0,0,0,'chall',0,0,0,null,0,0,0,0,null,null,null);
