Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778841033,to_date('23-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'To celebrate Local Government Awareness Week (LGAW), the Regional District of Okanagan-Similkameen collaborated with the Similkameen Elementary Secondary School to offer a unique perspective on local government this past week.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Students spent time from May 15 to 19 with RDOS directors and communications staff to learn more about how the municipal government works, along with various programs and services provided by the Regional District.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'On Monday, the RDOS visited grade five students at the school, including Cawston Director George Bush, Princeton Mayor and RDOS Vice-chair Spencer Coyneand Keremeos Mayor Jason Wiebe. The group addressed questions and shared their experiences as elected officials on the RDOS Board.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Local Government Awareness Week provides a wonderful opportunity to shed light on the services and programs the Regional District offers in our communities," Wiebe said in the news release.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Engaging with students and discussing my roles as a mayor and a member of the RDOS Board of Directors was an enjoyable experience."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Then, on Thursday, the students participated in the RDOS Board meeting through a Webex session, delving deeper into the workings of local government. Directors responded to the students'' inquiries, offering further insights into their responsibilities and duties. [maz, edu]','Grade 5 students learn from RDOS directors for Local Government Awareness Week','Internet',1,1,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=52325' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/lgaw-grade-5-students-info-release-photo-3_p3688364.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Penticton/427851/Grade-5-students-learn-from-RDOS-directors-for-Local-Government-Awareness-Week',0,null,0,0,null,0,0,0,0,'jglass',0,0,0,null,0,0,0,0,null,null,null);
