Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778508977,to_date('21-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'Penticton''s Total Pet is hosting a charity petting zoo to try to raise $10,000 to donate to an Okanagan-based wildlife rehabilitation centre.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Lilah and Eva Policicchio with Total Pet shared that the month of June is PAW month with Pet Valu, with each store picking a rescue of their choosing and then hosting a series of events for the duration of the month to raise funds and donate all of the proceeds to that charity.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"For our charity, we chose the Interior Wildlife Rehabilitation Society which rescues wildlife in Summerland," they said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Our goal for the month is to raise $10,000 to donate to the rescue in hopes to help them save many more animals.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'On May 27, the store will be hosting a petting zoo from 11 a.m. to 3 p.m. There is a $10 entry fee that will all be donated.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Animal lovers will get a chance to meet and interact with some pretty awesome animals. This will be the largest event Total Pet has ever put on but we are determined and hopeful it will be a successful event," they added.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We have gathered animal parent volunteers who will be bringing animals to attend at the petting zoo and we will also be having a BBQ with generous donations from Safeway."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Some of the animals in the petting zoo include goats, a miniature donkey, an alpaca, a calf, miniature horses, rabbits, a pig, parrots, ferrets, and various reptiles.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We want to do this event because we both have many animals of our own and definitely know how expensive they are. Interior Wildlife is almost one of the only rescues in the Okanagan that takes a variety of wildlife," they added.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We have many animals in the Okanagan that need saving and that means money so we are hoping with this donation they will be able to save many more animals and give them the chance they deserve."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"The two of us have put months of work, and volunteer time into organizing this, and are hoping for a huge turnout."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Head to Total Pet on May 27 at 402 Industrial Ave East. [env, forr]','Penticton pet store hosting charity petting zoo to help raise money for Interior Wildlife Rehabilitation Society','Internet',1,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=84368' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/screen_shot_2023-05-20_at_5.05.23_pm_p3688366.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Penticton/427853/Penticton-pet-store-hosting-charity-petting-zoo-to-help-raise-money-for-Interior-Wildlife-Rehabilitation-Society',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
