Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778998704,to_date('24-MAY-23','DD-MON-RR'),'Ming Pao News',to_date('01-JAN-70','DD-MON-RR'),'The BC government announced yesterday beginning June 1, 2023, communities in British Columbia can apply for funding aimed at helping seniors lead independent, active lives. This year''s funding is $500,000 in total.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"As people in BC age, our government has a responsibility to make sure seniors age with dignity and respect, and that includes having communities that are age-friendly," said Adrian Dix, Minister of Health. "I encourage local governments and Indigenous community leaders to apply for a grant that will lead to meaningful improvements locally for seniors." By 2031, nearly one-quarter of the province''s population will be age 65 or older. The Age-friendly BC program is facilitating independent living and community engagement among seniors by providing financial support to local governments and Indigenous communities.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Age-friendly grants are another way to support our seniors, and our government recognizes the crucial role this program plays," said Harwinder Sandhu, Parliamentary Secretary for Seniors'' Services and Long-Term Care. "The program aligns with our priorities, such as promoting accessibility and inclusion, and is a great opportunity for communities to provide increased supports and connections for their local seniors."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Age-friendly BC program is a partnership between the provincial government and BCHC, a provincewide not-for-profit organization that facilitates the ongoing development of healthy, thriving and resilient communities. For more information about the Age-friendly Communities Program, visit: www.bchealthycommunities.ca/programs/age-friendly-communities [hlth, zza, zhx]','Province provides age-friendly grants to improve seniors'' living ','Internet',0,1,0,null,to_date('24-MAY-23','DD-MON-RR'),to_date('24-MAY-23','DD-MON-RR'),null,null,'A06',null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,null,0,'krypto',0,0,null,0,0,0,0,'cdan',0,0,0,null,0,0,0,0,null,null,null);
