Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778164774,to_date('18-MAY-23','DD-MON-RR'),'CKNW',to_date('01-JAN-70','DD-MON-RR'),'Ken Sim talks about FIFA''s brand launch party last night to unveil the 2026 World Cup logo. The mayor of Vancouver is looking at options to increase the amount of short term accommodations, including hotels and Airbnbs. Sim doesn''t know exactly how many games Vancouver will host, but he wants as many as possible. [tacz, fin, maz]','Sim - 2026 FIFA World Cup','Talk Radio',0,1,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,'column','CKNW Simi Sara','CKNW Simi Sara',null,null,null,421,600,null,to_date('01-JAN-70','DD-MON-RR'),'778164774.m4a','2023/05/18/778164774.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'rfreeman',0,0,0,null,0,0,0,0,'not applicable',null,null);
