Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (779242667,to_date('25-MAY-23','DD-MON-RR'),'CFAX',to_date('01-JAN-70','DD-MON-RR'),'Adam Major has organized a fundraising memorial BBQ event for the Oak Bay municipal worker killed on the job last week. Steve Seekins left behind a young family, including two children. [pssg, lbrr]','Major - memorial BBQ','Talk Radio',0,1,0,null,to_date('25-MAY-23','DD-MON-RR'),to_date('25-MAY-23','DD-MON-RR'),null,null,null,'column','CFAX Mornings with Al Ferraby','CFAX Mornings with Al Ferraby',null,null,null,0,300,null,to_date('01-JAN-70','DD-MON-RR'),'779242667.m4a','2023/05/25/779242667.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'rfreeman',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (779282419,to_date('25-MAY-23','DD-MON-RR'),'Ming Pao News',to_date('01-JAN-70','DD-MON-RR'),'The province announced newcomers, including international students and foreign workers, will soon receive enhanced supports.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Anne Kang, Minister of Municipal Affairs, announced at a press conference yesterday that the province will increase funding for settlement services from $6 million to $25.6 million annually. These settlement services, delivered under the BC Settlement and Integration Services (BCSIS) program, empower temporary residents and naturalized citizens to successfully integrate into their new communities, find meaningful employment, access education and health care, and contribute to the social fabric of their new community.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The province said BC''s investment will enhance supports and services currently in place, improve workforce readiness for newcomers, expand outreach and build capacity in the settlement system, and support poverty reduction and homelessness prevention. The expanded settlement program will launch in spring 2024 and is expected to serve more than 40,000 clients per year.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Kan, who is an immigrant herself, said she knows how important it is to have access to services and supports upon arrival. "Newcomers are incredibly important to our past, present and future. The experience, skills and cultural perspectives they bring enrich the lives of everyone in BC. When newcomers thrive, our communities become stronger. The steps we''re taking today will help ensure that newcomers receive the services they need to flourish in BC." The Affiliation of Multicultural Societies and Service Agencies of BC (AMSSA) welcomes the announcement of increased funding to migrant services. Katie Crocker, CEO of AMSSA, said increased funding for the BCSIS program will enable settlement and integration service providers to better support temporary residents and naturalized citizens in their social and economic integration journey.','Province tripled settlement service funding from $6 million to $25.6 million annually ','Internet',0,1,0,null,to_date('25-MAY-23','DD-MON-RR'),to_date('25-MAY-23','DD-MON-RR'),null,null,'A05',null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,null,0,'krypto',0,0,null,0,0,0,0,'cdan',0,0,0,null,0,0,0,0,null,null,null);
