Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778150051,to_date('18-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'Major flooding is not expected this year due to lower snowpack, but the recent hot weather could change that if a storm next week brings significant rainfall.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Greg Wightman, utility services manager for the City of Kamloops, told Castanet officials are still not anticipating any significant flooding this year.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Wightman said the city receives information from Environment Canada and the B.C. River Forecast Center every day to ensure data is accurate.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"There''s certainly a lower snowpack this year than recent years, so that means less likelihood of flooding," he said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'But Wightman said the hot weather in recent days could be cause for some concern.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"The real concern right now is, if following this heat - when the high pressure ridge begins to break apart - if there were to be significant thunderstorms that would follow that, that would be problematic," he said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Wightman said recent improvements along Rivers Trail should ensure Riverside Park stays dry.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"[A dike] raised the elevation of protection in Riverside Park to protect our critical sewer infrastructure that''s in that park. So we should be in better shape than years past just based on that," he said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'He said there is a possibility that some flooding could be seen on the backside of McArthur Island and on the pathway below the train bridge behind Sandman Centre.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We''re not anticipating any major flooding at this point, but continuing to monitor forecasts," Wightman said. [maz, pssg, env, forr, embc]','City says flooding unlikely, but significant rainfall could change that','Internet',1,1,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=97390' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/img_4467_p3687170.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kamloops/427220/City-says-flooding-unlikely-but-significant-rainfall-could-change-that',0,null,0,0,null,0,0,0,0,'chall',0,0,0,null,0,0,0,0,null,null,null);
