Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778281057,to_date('19-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'The Kamloops-Thompson school district is looking to expand one of its drug prevention programs to include every school in the district.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'According to Vessy Mochikas, SD73''s assistant superintendent for inclusive education, the PreVenture program is an evidence-based, personality targeted intervention program aimed at preventing substance use among teens.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"It''s a research-based program that focuses on risk factors for youth substance misuse and mental health problems as a way to understand why early onset substance use is so high, concurrently at the same time as other mental health concerns, and future addiction," she said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The program sees students take a survey that identifies if they have personality traits that make them susceptible to potentially problematic drug and alcohol use.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"If they come out as having characteristic levels of those four personality types - it was sensation seeking, impulsivity, negative thinking and anxiety sensitivity - then they are invited to participate in two 90-minute sessions," Mochikas said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Students who are determined to have one of the personality traits have a higher likelihood for risk-taking behaviours, according to Mochikas.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Students learn to become aware of their personality traits and their current coping strategies, and are then taught to develop useful coping skills, set long-term goals and channel their personality traits to achieve their goals.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"So it''s a three-hour program delivered to folks identified as having a personality that is more susceptible to substance misuse," Mochikas said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"And so then not only does it help prevent those struggles, but it gives them positive coping strategies for everyday stresses for the rest of their lives."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Mochikas said the program is supported by Interior Health, which provides facilitators and training.','SD73 eyes expanding innovative drug prevention program to entire district','Internet',1,1,0,null,to_date('19-MAY-23','DD-MON-RR'),to_date('19-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=67848' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/sd73_logo_sign_p3687397.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kamloops/427348/SD73-eyes-expanding-innovative-drug-prevention-program-to-entire-district',0,null,0,0,null,0,0,0,0,'jglass',0,0,0,null,0,0,0,0,null,null,null);
