Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778769083,to_date('22-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'PEMBROKE, Ont. _ Ontario Provincial Police are investigating a suspected double homicide in Pembroke early this morning that left a third person with life-threatening injuries. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police say officers were called to a home on Mackay Street shortly before 3 a.m., where they found two people with life-threatening injuries. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Both were taken to hospital, where one was pronounced dead and the other remains as of this afternoon. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Officers found a third person dead near the scene shortly afterward. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police believe the victims were targeted and are asking the public to report any suspicious activity in the area, while being mindful of their own personal safety. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The investigation remains in its early stages and local residents should expect to see a large police presence. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'This report by The Canadian Press was first published May 22, 2023.','Two dead, one person in life threatening condition after Pembroke homicide: OPP ','CP News',1,1,0,null,to_date('22-MAY-23','DD-MON-RR'),to_date('22-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2108130241/_k/Gec0R71CssgUN4EE',0,null,0,0,null,0,0,0,0,'oscott',0,0,0,null,0,0,0,0,null,null,null);
