Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778773391,to_date('22-MAY-23','DD-MON-RR'),'Global News: BC 1',to_date('01-JAN-70','DD-MON-RR'),'A shift in weather has prompted renewed flood concerns across the Southern Interior, prompting a warning for residents living in trouble spots to get prepared.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '' || CHR(13) || CHR(10) || '"What we''re seeing really is a culmination of a week of very hot weather that''s really accelerated snowmelt rates and we see rivers around the province being very high," David Campbell, with the B.C. River Forecast Centre said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We see a fairly significant weather pattern change, with kind of a low-pressure system working its way across the province, bringing probably a couple of days of moderate to heavy rain through a number of regions of the province.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"With the rivers very full we''re expecting sort of an upswing and increase in flood hazard over the next couple of days."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Campbell said those living in flood-prone areas should get ready now, should the worst happen.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"(Water levels are) going to come up very quickly when the rain starts to fall, if it does," he said. "So if you need advance time to be prepared to get ready for this event, that now''s the time to do that. So, if you''re living on Mission Creek in the Okanagan, for example, now it''s probably a good time to prepare. If you''re at the Shuswap, now''s a good time to get prepared."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Multiple thunderstorm watches and warnings were issued in recent days by the Environment and Climate Change Canada.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'On Monday, convective precipitation is expected to continue with 15 to 25 millimeters of precipitation possible through the region, the River Forecast Centre said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Heavy rainfall is expected on Tuesday,  over much of the North Thompson, South Thompson and Bonaparte River watersheds.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Rainfall totals could range from 20-40 mm, with higher amounts expected on east-facing mountain slopes.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The river forecast service pointed out that a similar weather pattern caused flooding on Mission Creek near Kelowna in June 2022.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'A Flood Watch has been called for the Shuswap, Bonaparte River, North Thompson, South Thompson and Okanagan.','Rain puts Southern Interior back on flood watch','Internet',1,1,0,null,to_date('22-MAY-23','DD-MON-RR'),to_date('22-MAY-23','DD-MON-RR'),null,null,null,'column','Global News: BC 1','Global News: BC 1',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://globalnews.ca/news/9715503/now-is-a-good-time-to-get-prepared-rain-puts-southern-interior-back-on-flood-watch/',0,null,0,0,null,0,0,0,0,'artapia',0,0,0,null,0,0,0,0,null,null,null);
