Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777962820,to_date('17-MAY-23','DD-MON-RR'),'CJVB',to_date('01-JAN-70','DD-MON-RR'),'Women and girls in British Columbia living with addiction challenges will benefit from provincial funding for continued treatment and recovery services. Westminster House Society provides services and supports for women and girls affected by addiction, including women and girls struggling with nicotine, alcohol, prescription medication and substance use, and behaviour disorders, such as problematic eating and gambling. Jennifer Whiteside, Minister of Mental Health and Addictions, said when women make the brave decision to reach out for help, it''s vital the right services are in place to meet them, that''s why the government is investing in organizations like Westminster House Society. [mhaa, zhx]','Addictions support ','Radio News',0,1,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,null,'column','CJVB','CJVB',null,null,null,40,600,null,to_date('01-JAN-70','DD-MON-RR'),'777962820.m4a','2023/05/17/777962820.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'cdan',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777962907,to_date('16-MAY-23','DD-MON-RR'),'CFTV',to_date('01-JAN-70','DD-MON-RR'),'There are currently 63 active wildfires in the province and 19 fires are not under control. The evacuation alert in Fort St. John remains in place. Cliff Chapman, director of wildfire operations for BC Wildfire Service, said with hot weather continues this week, it''s going to speed up the spread of wildfires. Forests Minister Bruce Ralston said the BC Wildfire Service will hire 330 new crews this year to respond to wildfires and the province will provide support. [forr, embc, zhx]','Chapman/Ralston - BC wildfires update','TV News',0,1,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,null,'column','CFTV Fairchild Evening News','CFTV Fairchild Evening News',null,null,null,102,780,null,to_date('01-JAN-70','DD-MON-RR'),'777962907.mp4','2023/05/16/777962907.mp4',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'cdan',0,0,0,null,0,0,0,0,'Wildfire season','Issues','2023-05-17');
