Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778517474,to_date('21-MAY-23','DD-MON-RR'),'CHAN',to_date('01-JAN-70','DD-MON-RR'),'Paul Fader is among protestors calling for an end to the Cloverdale Rodeo. The animal activist argues the animals are subjected to unnecessary fear, pain, stress, discomfort and risk of injury. [agg, tacz]','Fader - Cloverdale Rodeo protest','TV News',0,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Global BC Morning News','Global BC Morning News',null,null,null,88,180,null,to_date('01-JAN-70','DD-MON-RR'),'778517474.mp4','2023/05/21/778517474.mp4',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778149544,to_date('18-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'Over $1 million in provincial emergency response funds have been used so far in responding to this spring''s flooding events in Cache Creek, according to a statement from village officials.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'In a news release posted on Tuesday, the village said it sustained what is possibly "the worst damage ever caused by the creek" during the annual snow melt this year.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The flooding began in the last few days of April.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"The creek turned itself into a river as it flowed faster and higher than the Bonaparte, pooling around Quartz Road, flowing down the highways, exposing infrastructure, eroding foundations, reclaiming nearby land and sending residents living along the creek running for safety," the statement said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The village noted crews, contractors and engineers worked around the clock until May 5 to contain the creek between 20-foot berms, but not before the floodwaters destroyed one home and damaged other private and public infrastructure.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"The creek was barely forced back into its channel when the Bonaparte reached a historic high level on May 9, triggering an evacuation of almost 300 more residents," the statement said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"As this was happening, crews never ceased working to respond to each new threat, assess the safety to the public, and repair the damage."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'As of Wednesday, Cache Creek remains under a state of local emergency. Although the Bonaparte River continues to run high and fast, the water levels have been slowly receding.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'According to officials, village infrastructure has sustained significant damage from the flooding event, with teams kept busy restoring basic community needs such as firehall, water, sewer and storm drain services.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The village noted over 20 pieces of machinery have been employed to undergo work throughout the community.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'It''s estimated that 300 loads of soil have been removed so far, with over 1,500 tons of riprap rock placed in order to protect critical infrastructure.','Over $1m in provincial funds spent in response to Cache Creek flooding','Internet',1,1,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=112741' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/cachecreekmay10-2-kh_p3687413.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kamloops/427355/Over-1-million-in-provincial-funds-spent-in-response-to-Cache-Creek-flooding',0,null,0,0,null,0,0,0,0,'artapia',0,0,0,null,0,0,0,0,null,null,null);
