Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778431018,to_date('20-MAY-23','DD-MON-RR'),'Global News: BC 1',to_date('01-JAN-70','DD-MON-RR'),'Search and rescue crews found a man''s body who jumped into fast-flowing waters in Cypress Falls Park to save a dog and was swept away. Kamil Karamali reports.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'A West Vancouver man died after entering a fast-flowing creek trying to rescue his dog.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'According to police, a married couple was walking their dog around 9 p.m. on Friday at Cypress Falls Park, when the dog was swept away after entering the water.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'In his attempt to retrieve the dog, the man in his 40s was also swept away by the fast current.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Rescue attempts to find and save the man in the evening were unsuccessful.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The man''s body was discovered just before 8 a.m. on Saturday. The dog was found deceased as well.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Out of respect for the privacy of the man''s family, West Vancouver Police will not be releasing his name.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"This was not the outcome we had all hoped for and it is an enormous tragedy for the family of the victim and our community," said Sgt. Mark McLean.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Our hearts go out to them".' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Victim services have been offered to the affected family and they are being supported, police said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Much of B.C. remains under a high streamflow advisory, however, there is no advisory for the North Shore.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Officials are warning British Columbians against being near fast-flowing rivers and creeks.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Stay clear of fast-flowing rivers and potentially unstable riverbanks," the River Forecast Centre urged.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Avoid recreational activities such as fishing, swimming, boating or hiking near high streamflow advisories." [env, embc, pssg]','West Vancouver man drowns trying to rescue his dog','Internet',1,1,0,null,to_date('20-MAY-23','DD-MON-RR'),to_date('20-MAY-23','DD-MON-RR'),null,null,null,'column','Darrian Matassa-Fung','Darrian Matassa-Fung',null,null,null,0,60,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://globalnews.ca/news/9713514/west-vancouver-man-drowns-dog-rescue/',0,null,0,0,null,0,0,0,0,'astrating',0,0,0,null,0,0,0,0,null,null,null);
