Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778163426,to_date('18-MAY-23','DD-MON-RR'),'BiV',to_date('01-JAN-70','DD-MON-RR'),'WestJet has started to cancel flights as talks with the pilots'' union remained at a "critical impasse," the company said Thursday, jeopardizing travel plans for thousands of passengers ahead of the May long weekend.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Some 1,800 pilots at the carrier and its Swoop subsidiary are poised to walk off the job as of 3 a.m. ET after the Air Line Pilots Association issued a strike notice Monday.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'WestJet issued a statement early Thursday saying negotiations with the union were stuck "in a stalemate." ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We remain at a critical impasse with the union and have been left with no choice but to begin taking the painful steps of preparing for the reality of a work stoppage," CEO Alexis von Hoensbroech said in a release.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Calgary-based company has begun to park the bulk of its fleet - 105 narrow-body 737s and seven wide-body 787 Dreamliners - using a "measured, phased and safe approach," the statement read.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The airline said its two regional services - WestJet Encore and WestJet Link, which connect its Calgary hub with smaller cities in British Columbia and Alberta - as well as some 737 flights will continue to operate.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'With more than 4,000 flights scheduled over the next seven days, WestJet carries 28 per cent of Canada''s domestic market, while Air Canada runs 47 per cent, according to Cirium.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'As of Thursday morning, the carrier had cancelled 92 flights or 17 per cent for that day, the aviation data firm''s figures show. Few flight cancellations had registered for Friday and afterward. But passengers are now unable to make online bookings for flights on major routes such as Calgary-Vancouver and Toronto-Calgary until Tuesday.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'WestJet''s online daily flight status tracker showed 32 of its 162 listed departures out of its Calgary hub had been cancelled, while 20 of the airline''s 50 flights out of Toronto''s Pearson airport had also been scrapped.','WestJet starts to cancel flights as pilot strike looms, negotiations in stalemate [DUPLICATE]','Internet',0,0,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,'column','The Canadian Press','The Canadian Press',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://biv.com/article/2023/05/westjet-starts-cancel-flights-pilot-strike-looms-negotiations-stalemate',0,null,0,0,null,0,0,0,0,'rfreeman',0,0,0,null,0,0,0,0,null,null,null);
