Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778855391,to_date('23-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'TORONTO _ Internationally trained engineers no longer require Canadian work experience to be licensed in Ontario. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Ontario Labour Minister Monte McNaughton says the province''s regulator for professional engineers has dropped the requirement, which he calls a "game changer" for qualified immigrant engineers that will help fill roughly 7,000 vacant positions. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Professional Engineers Ontario says up to 60 per cent of the license applicants it reviews every year are internationally trained. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'McNaughton says it''s the first regulatory association to make the change since the province introduced legislation in October 2021 that prevents more than 30 non-health-care-related professions and skilled trades from requiring Canadian experience qualifications. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'McNaughton called the requirement for Canadian work experience the "single biggest barrier" to immigrants landing well-paying jobs. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'He says he expects all regulators, from architects to land surveyors, to proactively drop the requirement before a deadline to do so by the end of the year. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Sara Asalya, executive director of Newcomer Women''s Service Toronto, applauded the change as a "huge win" for people advocating for the removal of unfair measures facing internationally trained professionals. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'This report by The Canadian Press was first published May 23, 2023.','Ontario engineer regulator drops Canadian experience qualification','CP News',0,0,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2108269084/_k/C5Lf7BT7PS7Aboeo',0,null,0,0,null,0,0,0,0,'chall',0,0,0,null,0,0,0,0,null,null,null);
