Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778855395,to_date('23-MAY-23','DD-MON-RR'),'CBYK',to_date('01-JAN-70','DD-MON-RR'),'Ward Stamer is calling on the BC Wildfire Service to bring in a campfire ban across the Interior. Barriere''s mayor suggests the fire danger rating is extreme, and he believes every effort must be made to prevent human-caused wildfires. Stamer also expresses his concerns about a fatal accident on Highway 5 this weekend that was complicated by road conditions and a lack of air ambulance services. [embc, pssg, forr, maz, tran, hlth]','Stamer - campfire ban','Talk Radio',0,1,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,'column','CBC Daybreak Kamloops','CBC Daybreak Kamloops',null,null,null,357,300,null,to_date('01-JAN-70','DD-MON-RR'),'778855395.m4a','2023/05/23/778855395.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'tday',0,0,0,null,0,0,0,0,null,null,null);
