Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778167869,to_date('18-MAY-23','DD-MON-RR'),'BiV',to_date('01-JAN-70','DD-MON-RR'),'B.C. will be getting an injection of hospitality workers thanks to a new partnership.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'British Columbia Hotel Association has partnered with the Mexican Consulate on a pilot project that will bring 100 people from Mexico to work in the B.C. hospitality industry through a streamlined process. The labour initiative will address the province''s skilled worker shortage and provide Mexican employees a chance to enhance their training.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"The BCHA is strongly committed to delivering innovative and results-oriented solutions to support our industry''s workforce needs," BCHA president and CEO Ingrid Jarrett said in a press release. "Following the overwhelming success of partnerships with the Consulate of Barbados and the Consulate of El Salvador, we enthusiastically celebrate another mutually beneficial partnership that will introduce a safe employment pathway for international workers.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We have a longstanding appreciation for Mexico, its people and its rich culture. Above all we hold immense respect and appreciation for the Mexican workforce, whose contributions have historically played a vital role in our province''s thriving hospitality sector."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Mexico''s National Employment Service of the Ministry of Labour and Social Welfare, in co-ordination with the Ministry of Tourism of Mexico, will find the workers, while BCHA''s workforce strategist, Alison Langford, will identify employers and placements. Individual contracts will be formalized between each employer and their selected candidate, with workers receiving on the job training and adequate housing.','B.C., Mexican governments reach deal to bring 100 hospitality workers to province [DUPLICATE]','Internet',0,0,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,'column','Kirk Penton/Castanet','Kirk Penton/Castanet',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://biv.com/article/2023/05/bc-mexican-governments-reach-deal-bring-100-hospitality-workers-province',0,null,0,0,null,0,0,0,0,'rfreeman',0,0,0,null,0,0,0,0,null,null,null);
