Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778510090,to_date('21-MAY-23','DD-MON-RR'),'Powell River Peak',to_date('01-JAN-70','DD-MON-RR'),'Police have determined driver error was the cause of a Tesla that crashed into the Horseshoe Bay BC Ferries terminal last January.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Following an analysis of the vehicle data, the investigators determined the collision to be human-caused," said West Vancouver Police Department spokesperson Sgt. Mark McLean.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The driver, a 68-year-old Vancouver man, was issued a ticket for driving without due care and attention under the Motor Vehicle Act, McLean said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'McLean said at the time of the collision the estimated damage to the ferry structure was over $30,000; on Friday, BC Ferries would only say that the damage was "in the thousands."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police described the car as having "suddenly accelerated" into the terminal on Jan. 14, leading to speculation as to what occurred.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'BC Ferries spokesperson Deborah Marshall said the incident occurred at a closed gate at one of the berths. Paramedics arrived at the scene and took the passengers to the hospital, she said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'In January 2021, the National Highway Traffic Safety Administration concluded an investigation of sudden accelerations of Tesla vehicles, finding driver error to be the source.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"More than 200 incidents involving Teslas unexpectedly accelerating and crashing were the fault of drivers confusing their brake and accelerator pedals, not a defect with the electric vehicles," reported the Washington Post. [tran, bcff, pssg]','Tesla crash at BC Ferries terminal deemed driver error','Internet',1,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Graeme Wood','Graeme Wood',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.prpeak.com/bc-news/tesla-crash-at-bc-ferries-terminal-deemed-driver-error-7027100',0,'krypto',0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
