Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (779302503,to_date('24-MAY-23','DD-MON-RR'),'CHNM',to_date('01-JAN-70','DD-MON-RR'),'After the announcement of $701m in funding by the provincial and federal governments, Vancouver-based company AbCellera is expanding its antibody research and development capacity and planning to have a new biotech campus. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Premier David Eby explains how COVID-19 illustrated the potential of this sector that provides the real practical benefits to the health of everybody around the world. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The expansion project will create more than 400 jobs while ensuring world-leading medicines are developed in Canada for Canadians and people globally, Eby says. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Federal Innovation Science and Technology Minister Francois-Philippe Champagne says they want to make sure that a world class life-science sector is build in BC. [zhj, jtst, pdpe, zpz]','Eby/Champagne - AbCellera funding','TV News',0,1,0,null,to_date('25-MAY-23','DD-MON-RR'),to_date('25-MAY-23','DD-MON-RR'),null,null,null,'column','OMNI Punjabi News','OMNI Punjabi News',null,null,null,0,1200,null,to_date('01-JAN-70','DD-MON-RR'),'779302503.mp4','2023/05/24/779302503.mp4',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'asidhu',0,0,0,null,0,0,0,0,'AbCellera funding','Proactive','2023-05-25');
