Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (779227737,to_date('25-MAY-23','DD-MON-RR'),'CBU',to_date('01-JAN-70','DD-MON-RR'),'Jeff Guignard warns the creditor protection the Donnelly Group is seeking is just part of the bigger picture when it comes to struggling bars and restaurants in BC. The ABLE BC executive director estimates half of the hospitality industry is either losing money or barely breaking even. [jtst, fin]','Guignard - Donnelly Group creditor protection ','Talk Radio',0,1,0,null,to_date('25-MAY-23','DD-MON-RR'),to_date('25-MAY-23','DD-MON-RR'),null,null,null,'column','CBC Early Edition','CBC Early Edition',null,null,null,0,300,null,to_date('01-JAN-70','DD-MON-RR'),'779227737.m4a','2023/05/25/779227737.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'lgranberg',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778551869,to_date('21-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'Severe thunderstorm watches have been issued once again Sunday for the Okanagan and parts of the Kootenays.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Several storms passed through on Saturday, and late last week, bringing thousands of lightning strikes, but also significant rainfall in some areas.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'There is a cluster of new out-of-control, lightning-caused fires in a mountainous area northeast of Seymour Arm, and a small lightning-caused fire is being held in the Currie Creek area near Cherryville. The BC Wildfire Service website shows only a few other fires sparked by lightning in the Kamloops Fire Centre on Saturday, and they are all under control.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Environment Canada meteorologist Jonathan Bau told Castanet there were about 5,000 lightning strikes across British Columbia on Saturday and early Sunday, with the bulk of them - about 3,000 - in the Thompson-Okanagan region.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'However, he adds that many of the thunderstorms were accompanied by rain, with some notable downpours.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"In the last 24 hours, the highest amount I can see is the highway station at McCulloch, just up Highway 33 to the east. That one seems to be the winner at 21 millimetres," said Bau. "Pennask picked up 15 and Summerland picked up 10 mm."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'He says the thunderstorms herald the breakdown of a ridge of high pressure that has brought unseasonably hot weather to the BC Southern Interior.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'A number of temperature records were broken for May 20 on Saturday, including in Kelowna (30.5 C), Kamloops (32.6 C), Vernon (30.2 C), Merritt (32.4 C) and Osoyoos (33.3 C). All but Osoyoos'' previous May 20 record were more than 100 years old.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'A full list of Saturday''s records can be found here. [forr, embc, pssg, env]','Thunderstorms and record heat through first half of long weekend','Internet',1,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=54655' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/may_18_2023_lightning_storm_01_copy_p3688465.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kelowna/427905/Thunderstorms-and-record-heat-through-first-half-of-long-weekend',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
