Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778167839,to_date('18-MAY-23','DD-MON-RR'),'DailyHive',to_date('01-JAN-70','DD-MON-RR'),'Mounties in Coquitlam are investigating after a man was shot Wednesday evening near a shopping complex.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police say officers responded around 7:30 pm to David Avenue and Coast Meridian Road to find a man who was severely injured after a shooting. He was taken to hospital with life-threatening injuries.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"This area was highly populated at the time of the shooting which is very concerning," Cpl. Alexa Hodgins with Coquitlam RCMP said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police believe the incident was targeted and say a suspect fled in a silver or grey four-door sedan.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'About 20 minutes later, a similar vehicle was found on fire at Cape Horn Avenue and United Boulevard. Police believe it was the suspect''s vehicle.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Now, police are asking anyone who may have seen the vehicle or its driver to contact investigators.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"If you have dash-cam or cellphone video from the area or surrounding streets and alleyways of the shooting or vehicle fire between 7:15 pm and 8:15 pm to please contact the Coquitlam RCMP at 604-945-1550," Hodgins said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The file number associated with the investigation is 2023-12269.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '  You might also like: - "Mass car-keying" at Coquitlam dealership sparks hunt for suspect - Several streets closed after wild police chase in New West (VIDEO) - New Westminster stabbing victim screams for help in apartment courtyard','Targeted shooting in Coquitlam leaves man with life-threatening injuries','Internet',1,1,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,'column','Megan Devlin','Megan Devlin',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://dailyhive.com/vancouver/coquitlam-shooting-targeted-life-threatening-injuries',0,null,0,0,null,0,0,0,0,'richard',0,0,0,null,0,0,0,0,null,null,null);
