Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778172102,to_date('18-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'TORONTO - An Ontario First Nation has filed a lawsuit against the province and the federal government alleging a large swath of its land was stolen. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Garden River First Nation alleges the predecessors of the federal and provincial governments coerced it to sign a treaty that gave up its land. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Chief Andy Rickford claims the governments took 70 per cent of the First Nation''s land in a treaty signed in 1859. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Rickford and dozens of other band members have descended upon Queen''s Park today to mark the launch of the suit. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Rickford says he is hoping the legal challenge prompts discussion with the province. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Garden River is looking to reclaim land east of Sault Ste. Marie, Ont. 
