Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778986619,to_date('24-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'A 39-year-old man was killed and a second man was sent to hospital with life-threatening injuries on Wednesday after an early-morning double shooting north of Toronto, police said. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Officers responded to reports of a shooting at an industrial plaza in Vaughan, Ont., around 3:50 a.m. Wednesday, York Regional Police Sgt. Clint Whitney told reporters gathered at the scene. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police found two men with gunshot wounds, he said. A 39-year-old man died at the scene and a 27-year-old man was sent to hospital in life-threatening condition. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"This gun violence is devastating," Whitney said. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police said the shooting took place outside the plaza, located on Creditstone Rd., just north of Highway 7. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Initial reports suggested the shooting was connected to a recording studio in the plaza, though police had yet to confirm that, Whitney said. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'There were "numerous" people in the area at the time and police were appealing for witness to come forward, Whitney said. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'No suspect information had been released as of Wednesday morning.','One dead, one injured in Vaughan, Ont., double shooting: police','CP News',1,1,0,null,to_date('24-MAY-23','DD-MON-RR'),to_date('24-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2108440440/_k/Mue9DVvU2ijeNSDB',0,null,0,0,null,0,0,0,0,'chall',0,0,0,null,0,0,0,0,null,null,null);
