Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777892497,to_date('17-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'The heatwave baking B.C. could potentially create extreme fire conditions, but the minister of forests says the province is prepared.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Minister of Forests Bruce Ralston and BC Wildfire Service director Cliff Chapman spoke to reporters Tuesday at the Kamloops Wildfire Centre. Chapman gave a grim warning about the potential for a difficult fire season.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'He said 50,000 hectares of the province have been scorched so far this year, up significantly from the 10-year average of 11,000 hectares by this time.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Chapman also said Environment Canada has forecasted that the temperature in the coming months will be above the normal seasonal weather.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Ralston touted recent changes made within BCWS, which beefed up staffing and made it a year-round agency.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Managing emergency and natural hazards is a 365 day operation. That''s why we''ve made those large investments - the largest in the history of the BC Wildfire Service - and doubled annual funding for wildfire prevention programs," he said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"The new Ministry of Emergency Services and Climate Resilience is the government''s direct response to what we anticipate due to climate change - more intense fires and longer fire seasons."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'BCWS has hired 330 new recruits this year, up from 200 in a typical year.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Ralston said Victoria is committed to the fire fight should BCWS need additional resources.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"If further resources are needed, whether it''s airplanes or initial attack crews or any of the other groups that are necessary to successfully fight fires, they will be available," he said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Chapman said BCWS is expecting challenging conditions in the coming days.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"[With] fuel conditions being what they are and the weather being what it is, it is going to be challenging suppression efforts across the province for us," he said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'He said the heat wave is expected to break early next week, which could mean strong winds and dry lightning.','Heat wave makes for troubling fire conditions, but BCWS says it''s ready','Internet',1,1,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=220417' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/427104_0.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kamloops/427104/Heat-wave-makes-for-troubling-fire-conditions-but-BCWS-says-it-s-ready',0,null,0,0,null,0,0,0,0,'jglass',0,0,0,null,0,0,0,0,null,null,null);
