Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778855493,to_date('23-MAY-23','DD-MON-RR'),'BiV',to_date('01-JAN-70','DD-MON-RR'),'Four things to watch for in the Canadian business world in the coming week:' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'BlackBerry investor presentation' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'BlackBerry is set to hold an event focused on retail shareholders on Tuesday when Mattias Eriksson, president of BlackBerry IoT, and John Giamatteo, president of BlackBerry Cybersecurity, are expected to take questions. The company announced a review of strategic alternatives earlier this month that could see it break up its operations. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Big bank earnings' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Canada''s big banks will begin reporting their second-quarter results on Wednesday when Scotiabank and Bank of Montreal report their earnings. CIBC, Toronto-Dominion Bank and Royal Bank of Canada are scheduled to report its results on Thursday.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'CPP results' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'CPP Investments, the country''s largest pension fund manager, is scheduled to release its latest results and annual report on Wednesday morning. The fund invests the assets of the Canada Pension Plan that aren''t currently needed to pay benefits.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Metro CEO speech' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Metro chief executive Eric La Fl裨e will give a speech to the Canadian Club of Montreal on Thursday. The head of the grocery and drugstore retailer is expected to talk about its acquisition of the Jean Coutu Group in 2018 and his vision for the company.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'This report by The Canadian Press was first published May 21, 2023.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Companies in this story: (TSX:MRU, TSX:BB, TSX:BNS, TSX:BMO, TSX:CM, TSX:TD, TSX:RY)' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Canadian Press','Four things to watch for in the Canadian business world in the coming week (May 23-26) [DUPLICATE]','Internet',0,0,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,'column','The Canadian Press','The Canadian Press',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://biv.com/article/2023/05/four-things-watch-canadian-business-world-coming-week-may-23-26',0,null,0,0,null,0,0,0,0,'richard',0,0,0,null,0,0,0,0,null,null,null);
