,0,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,'column','The Canadian Press','The Canadian Press',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://biv.com/article/2023/05/investor-occupants-made-almost-10-bc-homeowners-2020-statistics-canada',0,null,0,0,null,0,0,0,0,'richard',0,0,0,null,0,0,0,0,null,null,null);
