Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777171025,to_date('12-MAY-23','DD-MON-RR'),'CKNW',to_date('01-JAN-70','DD-MON-RR'),'Vaughn Palmer reflects on the exhausting nature of the sprint sitting of the Legislature, remarking in particular on Harry Lali''s defection to BC United yesterday. The Vancouver Sun notes the BC NDP provided reminders about Lali''s time with the party, suggesting BC United will regret taking him on. Palmer also discusses the continuing BC Housing audit saga, speculating on the viability of Housing Minister Ravi Kahlon''s threat not to renew BC Housing''s contracts with Atira. [zpz, pdpe, hozz]','Palmer - Lali defection/BC Housing audit','Talk Radio',0,1,0,null,to_date('12-MAY-23','DD-MON-RR'),to_date('12-MAY-23','DD-MON-RR'),null,null,null,'column','CKNW View From Victoria','CKNW View From Victoria',null,null,null,14,600,null,to_date('01-JAN-70','DD-MON-RR'),'777171025.m4a','2023/05/12/777171025.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'tday',0,0,0,null,0,0,0,0,'BC Housing audit','Issues','2023-05-12');
