Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777615363,to_date('15-MAY-23','DD-MON-RR'),'CBU',to_date('01-JAN-70','DD-MON-RR'),'Jonathan Morris describes how peer-assisted care teams are trained to respond, engage and de-escalate a situation when someone is experiencing a mental health crisis in BC. The CEO of Canadian Mental Health Association''s BC division says the PACTs have proven to be quite effective in reducing the need for police to respond to a mental health crisis event. [pssg, mhaa, hlth]','Morris - peer assisted care teams','Talk Radio',0,1,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),null,null,null,'column','CBC Early Edition','CBC Early Edition',null,null,null,480,1080,null,to_date('01-JAN-70','DD-MON-RR'),'777615363.m4a','2023/05/15/777615363.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'rfreeman',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777165419,to_date('12-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'A Kamloops city councillor says comments made about his wife and business connections by Mayor Reid Hamer-Jackson during a committee meeting Thursday were "inappropriate," and such behaviour has no place around the council table.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Coun. Mike O''Reilly is the chair of a select governance committee tasked with reviewing committee structure and terms of reference in the wake of sweeping changes made by the mayor to the city''s standing committees.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Hamer-Jackson chose to remove some councillors as chairs and appoint citizens to committees - including some friends and people who financially supported his election campaign. He has since maintained he chose the individuals based solely on their expertise.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The governance committee held what is intended to be its final meeting on Thursday, approving a number of recommendations that will go before council for adoption at a future date.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'During the meeting, Hamer-Jackson repeatedly brought up the mayor''s role, as laid out in the community charter, to establish appointments to standing committees.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Hamer-Jackson then told the committee he had previously been concerned about O''Reilly chairing the now-paused development and sustainability standing committee due to the councillor''s business connections, and because O''Reilly''s wife works in the city''s planning department.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'O''Reilly is the president and CEO of Comet Industries. The company plans to turn a 190-acre parcel of land in southwest Kamloops into a light industrial subdivision. O''Reilly has recused himself from discussion and votes whenever the matter has come before council.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Hamer-Jackson said as mayor, he''s the one who was responsible for picking the committee members - and he needed to avoid any perceived conflict.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"All I was trying to do is trying to alleviate any type of issues that would happen through the city," he said.','Councillors push back on ''inappropriate'' comments from Kamloops mayor','Internet',1,1,0,null,to_date('12-MAY-23','DD-MON-RR'),to_date('12-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=84050' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/cityhall2kh_p3685428.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kamloops/426286/Councillors-push-back-on-inappropriate-comments-from-Kamloops-mayor',0,null,0,0,null,0,0,0,0,'jglass',0,0,0,null,0,0,0,0,null,null,null);
