Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777165394,to_date('12-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'The Bonaparte River has likely peaked, according to B.C. River Forecast Centre models.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The river''s discharge at Cache Creek is now below 90 metres squared per second - still well above a 20-year flood level, but down about 10 per cent since Wednesday''s peak.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Village officials on Thursday extended evacuation orders until at least May 15. Information officer Wendy Coomber said that decision was made due to the impending heat wave slated to bake B.C., which could increase snow melt and cause river levels to rise.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'An estimated 300 Cache Creek residents have been ordered out of their homes due to flooding. Many are in Kamloops, where an emergency support services centre has been set up on McArthur Island.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Coomber said Thursday village officials are worried Cache Creek itself, which began to flood late last month, could rise again with increased snowmelt.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'This story will be updated as more information becomes known. [pssg, env, forr, embc]','Worst of Bonaparte River high water likely over, river forecast shows','Internet',1,1,0,null,to_date('12-MAY-23','DD-MON-RR'),to_date('12-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=197981' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/img_4451_copy_p3685525.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kamloops/426351/Worst-of-Bonaparte-River-high-water-likely-over-river-forecast-shows',0,null,0,0,null,0,0,0,0,'jglass',0,0,0,null,0,0,0,0,null,null,null);
