Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778533867,to_date('21-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'A rescind of the remaining evacuation orders and alerts is coming for Okanagan Indian Band residents, says the Emergency Operations Centre.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'In a Facebook post to community members Saturday night, the OKIB EOC said it''s currently working toward rescinding the Evacuation Order and Evacuation Alert for "all remaining properties," following extensive flooding in the area over the past several weeks.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Demobilization work of flood mitigation measures is currently ongoing in the Parker''s cove area and removal of flood mitigation measures will continue throughout this week and early next week," explained the Facebook post.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The EOC is "standing down" for the remainder of the long weekend. It will be open Tuesday 10 a.m. to 2 p.m. and Thursday 9 a.m. to 4:30 p.m.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'OKIB communities started receiving evacuation alerts and orders on May 2 after Whiteman''s Creek overflowed its banks and poured through the community.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Some evacuation orders have already been rescinded. Residents of Raven Road along Saskatoon and adjacent to the mouth of Whiteman''s Creek have already been allowed back.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The band is reminding residents to contact their insurance company for available supports. The provincial government announced earlier this month people impacted by the freshet flooding are eligible for disaster financial assistance.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Applications must be submitted to the Ministry of Emergency Management and Climate Readiness within 90 days of the event declaration.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Access the DFA application here. [tnf, forr, embc, pssg, env, maz]','OKIB says it''s working on rescinding evacuation orders and alerts','Internet',1,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=91304' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/img_7246_p3669889_p3688449.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Vernon/427896/OKIB-says-it-s-working-on-rescinding-evacuation-orders-and-alerts',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
