Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (779279204,to_date('25-MAY-23','DD-MON-RR'),'CBYK',to_date('01-JAN-70','DD-MON-RR'),'Jennifer Biddlecome needs to sell her flood-damaged home in Merritt to be able to pay for live-saving medical treatment for her husband, but every person who was interested wanted confirmation from the city of Merritt that they would have building permits approved. The Merritt homeowner notes the city was willing to provide the a letter stating that the building permits would be approved, but the city is planning to get bylaws approved to prevent building on the street because the city plans to purchase the land at a later date to implement dykes for flood mitigation. [hlth, maz, hozz, fin, embc, pssg, forr, env]','Biddlecome - Merritt home sale','Talk Radio',0,1,0,null,to_date('25-MAY-23','DD-MON-RR'),to_date('25-MAY-23','DD-MON-RR'),null,null,null,'column','CBC Daybreak Kamloops','CBC Daybreak Kamloops',null,null,null,0,480,null,to_date('01-JAN-70','DD-MON-RR'),'779279204.m4a','2023/05/25/779279204.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'jglass',0,0,0,null,0,0,0,0,null,null,null);
