Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (779282060,to_date('25-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'The Block on Bernard Avenue in downtown Kelowna has another tenant.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'A locally owned daycare, ProducKIDvity, has signed a 15 year lease with Mission Group and Nicola Wealth to be one of the first to call The Block on Bernard Ave. home.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Block is expected to open in late 2023 and ProducKIDvity''s Block on Bernard location will provide over 100 childcare spots including highly sought after infant child care as well as 3-5 preschool programming.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The new location will occupy the entire 6th floor and include a 3500 square foot outdoor patio. ProducKIDvity are also acquiring 4500 square feet of office space on the 7th floor for co-working and flexible office space to childcare customers and other businesses, freelancers, and entrepreneurs seeking office space.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"To say we are excited about this project would be an understatement," says Alex Carnio, CEO of ProducKIDvity. "We view this as a turning point in our business as the Block will be truly home to the future of Kelowna. Being able to provide an office tower daycare concept will be the first of its kind in the city and is an exciting opportunity to prove that we are continuing to break the mold of traditional childcare."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The daycare''s Block on Bernard location will be the only childcare facility in Kelowna that will be open six days a week and will offer extended hours from 6:30 a.m. to 7 p.m.. The daycare will offer an in-house food program for students and co-workers, as well as a family take home option.','ProducKIDvity introduces premium daycare facility to Kelowna','Internet',1,1,0,null,to_date('25-MAY-23','DD-MON-RR'),to_date('25-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=98281' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/bernard-block-office-3-1280x920._p3689470.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kelowna/428547/ProducKIDvity-introduces-premium-daycare-facility-to-Kelowna',0,null,0,0,null,0,0,0,0,'rfreeman',0,0,0,null,0,0,0,0,null,null,null);
