Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778583888,to_date('21-MAY-23','DD-MON-RR'),'CHAN',to_date('01-JAN-70','DD-MON-RR'),'Lisa Dominato is among the city politicians converging in Toronto for the municipal leaders'' conference next week, suggesting finances will be a focus of the talks. The Vancouver city councillor argues Canada needs to recognize municipalities are not able to keep up with the pace of change, noting some communities have been waiting for new schools for over a decade while others are dealing with crumbling infrastructure. Municipal consultant Brent Tedorian argues municipalities should be getting more funding. [maz, edu, fin]','Dominato/Tedorian - municipal leaders'' conference','TV News',0,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Global BC News Hour','Global BC News Hour',null,null,null,132,240,null,to_date('01-JAN-70','DD-MON-RR'),'778583888.mp4','2023/05/21/778583888.mp4',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'astrating',0,0,0,null,0,0,0,0,'not applicable',null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778533866,to_date('21-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'UPDATE 9:32 a.m.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The lights are back on to thousands of BC Hydro customers on the Westside.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'A tree across the line caused a power outage to nearly 3,500 customers in West Kelowna early Sunday morning. It affected homes and businesses south of Cougar Road, east of Brendalee Road and west of Sunnybrae Road.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'BC Hydro says crews restored electricity at about 9:00 a.m.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'ORIGINAL 6:55 a.m.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Thousands are without power in West Kelowna Sunday morning.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'At 6:30 a.m., the outage hit 3,475 homes in West Kelowna, according to BC Hydro.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The cause of the outage remains under investigation at this time.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Crews are attending the outage to repair it, but it''s not clear at this time when restoration of power is expected. [empr]','A tree across a line caused a widespread power outage in West Kelowna Sunday morning','Internet',1,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=46986' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/screen_shot_2023-05-21_at_6.55.27_am_p3688428.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/West-Kelowna/427883/A-tree-across-a-line-caused-a-widespread-power-outage-in-West-Kelowna-Sunday-morning',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
