Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777165388,to_date('12-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'UPDATE: 10:22 p.m.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Cache Creek evacuation orders have been extended by three days.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Residents are now not expected to return home until at least May 15, said Wendy Coomber, information officer with the Village of Cache Creek''s emergency operations centre.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'That''s because the warm temperatures in the immediate forecast may cause more snow melt and affect the Bonaparte River - but not right away. Coomber said the river takes a few days to register the melt.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Coomber said the village is waiting to see if things get worse. If they do, it''s expected it would happen Monday or Tuesday.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Village officials don''t know just how much infrastructure has been affected by flooding.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"As the water goes down, it reveals a little bit more [damage]. It''s actually the low water, we''re told by our engineers that causes the damage, not the not the high water," Coomber said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"So as the water goes down it erodes a little more, and we''re still experiencing fairly high flows of the river. The creek isn''t so bad anymore and we are fixing bank damage and infrastructure damage that it''s caused. But the river is still hiding all of its little secrets."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Coomber says the culvert on Highway 97 has suffered significant erosion damage and has uncovered one of the town''s main water mains.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Village crews are expected to begin work on the water main on Friday.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Cache Creek community park remains off limits to the public.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'UPDATE: 5:11 p.m.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Bonaparte River hasn''t seen any major breaches over its banks, but village officials in Cache Creek worry large amounts of unmelted snow could cause more flooding in the coming days as the temperature rises.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We''ve been told that there are unreported large amounts of snow north of us that are just waiting for warm weather and sunshine," Wendy Coomber, information officer with the Village of Cache Creek''s emergency operations centre, told Castanet Kamloops.','Cache Creek evacuation orders extended three days with hot weather in forecast','Internet',1,1,0,null,to_date('12-MAY-23','DD-MON-RR'),to_date('12-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=480551' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/426136_0.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kamloops/426136/Cache-Creek-evacuation-orders-extended-three-days-with-hot-weather-in-forecast',0,null,0,0,null,0,0,0,0,'jglass',0,0,0,null,0,0,0,0,null,null,null);
