Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777755727,to_date('16-MAY-23','DD-MON-RR'),'CHAN',to_date('01-JAN-70','DD-MON-RR'),'Bernard Lewall confirms WestJet pilots have issued 72-hour strike notice. The Air Line Pilots Association rep says the two sides are still far apart in two of three key areas so the association made the difficult decision to issue the strike notice. The notice means pilots could go on strike Friday, just before the Victoria Day long weekend. [jtst, tran, tacz, lbrr]','Lewall - WestJet pilots strike notice','TV News',0,1,0,null,to_date('16-MAY-23','DD-MON-RR'),to_date('16-MAY-23','DD-MON-RR'),null,null,null,'column','Global BC Morning News','Global BC Morning News',null,null,null,287,300,null,to_date('01-JAN-70','DD-MON-RR'),'777755727.mp4','2023/05/16/777755727.mp4',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'oscott',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777749560,to_date('16-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'"Flexible, adaptable spaces" will likely be worked in to plans for a new elementary school being built in Pineview Valley following a meeting with community members, the SD73 board was told Monday night.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Pineview Valley Community Engagement Committee meeting, held on April 27, saw committee members discussing the project''s preliminary budget, design and site plans.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The designers of the capital project, Station One Architects, shared examples of their work from other B.C. school districts, highlighting design changes from the traditional school model that they plan to implement at Pineview Elementary.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'These changes would include more glass, pods of classrooms with common areas in between to generate more opportunities for collaboration and break out rooms for groups and meetings.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Feedback from the committee about the plans included discussions of the importance of having multi-purpose and outside spaces to be used by students and teachers, such as an indoor kitchen space that would open up onto the school''s lawn and the adjacent Python Lake.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Flexible, adaptable spaces was brought up as a consistent theme and we will be having to balance that versus some of the other requests that are dear to us," said Director of Facilities, Art McDonald, during the school district''s regular public board meeting on Monday.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Committee members also discussed how to design outdoor spaces to be used for Indigenous ceremonies, smudging and gatherings, with mentions of using a covered outdoor space for these purposes.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Discussions of how to use the Neighbourhood Learning Centre covered using the space as an Aboriginal Education room, a child care centre for before and after school care, or to expand the gym.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"To my surprise, there wasn''t a huge request for early years childcare. There was more support for things like the extended gym for after hours," said McDonald.','Community wants to see ''flexible'' spaces in new Pineview school, trustees told','Internet',1,1,0,null,to_date('16-MAY-23','DD-MON-RR'),to_date('16-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=116260' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/screen_shot_2022-12-09_at_10.29.23_am_p3643203_p3686471.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kamloops/426908/Community-wants-to-see-flexible-spaces-in-new-Pineview-school-trustees-told',0,null,0,0,null,0,0,0,0,'jglass',0,0,0,null,0,0,0,0,null,null,null);
