Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777300851,to_date('13-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'Police in India say they are looking for three men in connection with the deaths of a family from Gujarat trying to cross into the United States by boat through Akwesasne, Que., in March. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Indian police allege the men were involved in running immigration firms that are used by people to enter countries with fake documents. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Four Indian nationals whose bodies were among eight pulled from the St. Lawrence River had been travelling in Canada on a tourist visa from their home state of Gujarat. They included the father, Praveen Chaudhari, 50; mother, Daksha, 45; daughter, Vidhi, 23; and son, Meet, 20. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Achal Tyagi, superintendent of police for the city of Mehsana, in the western state of Gujarat, says authorities have put out a lookout circular for three men: Nikulsinh Vihol, Sachin Vihol and Arjunsinh Chavda. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'They face charges of culpable homicide not amounting to murder, criminal breach of trust, cheating and dishonestly inducing delivery of property and criminal conspiracy. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Tyagi says a police complaint is registered against the men and the case is still in the early stages of investigation. According to that complaint, translated by The Canadian Press, at least one of the men was living in Canada. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The four other people who died were a Romanian family from the Toronto area who were fleeing after receiving a deportation order. They were identified as Florin Iordache, his wife Cristina (Monalisa) Zenaida Iordache, as well as their Canadian-born children, two-year-old daughter Evelin and one-year-old son Elyen.','Indian cops hunt suspects in illegal crossing deaths of family to US from Akwesasne','CP News',1,1,0,null,to_date('13-MAY-23','DD-MON-RR'),to_date('13-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2106546611/_k/w2Y1qyrpCAg23NyR',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
