Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778297674,to_date('19-MAY-23','DD-MON-RR'),'BiV',to_date('01-JAN-70','DD-MON-RR'),'Statistics Canada says retail sales nationwide fell 1.4 per cent to $65.3 billion in March.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'However, the agency says core retail sales - which exclude gasoline stations and fuel vendors and motor vehicle and parts dealers - rose 0.3 per cent in the month.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'B.C. was the only province to see retail sales grow, up 0.9 per cent to reach $8.9 billion.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Meanwhile, retail sales in Metro Vancouver grew two per cent.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'This comes after B.C. was registering the largest declines in Canada in February. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Sales at motor vehicle and parts dealers across Canada dropped 4.4 per cent in March, their first decline in eight months as sales at new car dealers fell 4.8 per cent.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Sales at gasoline stations and fuel vendors were down 3.9 per cent.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Meanwhile, sales at building material and garden equipment and supplies dealers rose 1.6 per cent and sales at sporting goods, hobby, musical instrument, book, and miscellaneous retailers gained 1.6 per cent.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'In volume terms, Statistics Canada says retail sales fell 1.0 per cent in March.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'This report by The Canadian Press was first published May 19, 2023.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Canadian Press','BC retail sales jump 0.9% in March, only province to post growth: StatCan [DUPLICATE]','Internet',0,0,0,null,to_date('19-MAY-23','DD-MON-RR'),to_date('19-MAY-23','DD-MON-RR'),null,null,null,'column','The Canadian Press','The Canadian Press',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://biv.com/article/2023/05/bc-retail-sales-jump-09-march-only-province-post-growth-statcan',0,null,0,0,null,0,0,0,0,'rfreeman',0,0,0,null,0,0,0,0,null,null,null);
