Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777618444,to_date('15-MAY-23','DD-MON-RR'),'CBU',to_date('01-JAN-70','DD-MON-RR'),'Craig Jones discusses a new study which found that 85% of evictions in BC are deemed to be no fault of the tenants and that this percentage is much higher than in the rest of Canada. The associate director of the UBC Housing Research Collaborative says BC tenants are more likely than other Canadians to be asked to leave for reasons such as landlords needing to use the property themselves, or the landlord selling or renovating the property. [hozz]','Jones - no fault evictions ','Talk Radio',0,1,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),null,null,null,'column','CBC Early Edition','CBC Early Edition',null,null,null,388,420,null,to_date('01-JAN-70','DD-MON-RR'),'777618444.m4a','2023/05/15/777618444.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'oscott',0,0,0,null,0,0,0,0,null,null,null);
