Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778745595,to_date('22-MAY-23','DD-MON-RR'),'DailyHive',to_date('01-JAN-70','DD-MON-RR'),'BC Ferries is having a rough end to its long weekend after an outage Monday morning impacted its website, app, and phone system.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Travellers looking to check their ferry schedule won''t be able to find information on the website. However, BC Ferries is still sharing updates on its sailing conditions.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Our IT team is aware and currently working on a fix [for the outage]," a tweet reads. "We will keep customers updated [on Twitter] as more information becomes available."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Daily Hive has reached out to BC Ferries for additional information.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '> #BCFHeadsUp > An IT outage is impacting access to our website, app & call centre. We have identified the issue & we are working on restoring service as quickly as possible. We apologize to our customers who have been impacted, this morning. We will continue to provide updates here. >  > - BC Ferries (@BCFerries) May 22, 2023','BC Ferries experiencing site, app and phone system outage Monday','Internet',1,1,0,null,to_date('22-MAY-23','DD-MON-RR'),to_date('22-MAY-23','DD-MON-RR'),null,null,null,'column','Nikitha Martins','Nikitha Martins',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://dailyhive.com/vancouver/bc-ferries-outage-may',0,null,0,0,null,0,0,0,0,'artapia',0,0,0,null,0,0,0,0,null,null,null);
