Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778565646,to_date('21-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'Highway 3A closed due to landslide' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'UPDATE: 3 p.m.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'An Olalla resident is stuck on the highway just minutes away from home.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Kesa Matson shared on Facebook just after 2 p.m. that Highway 3A has been shut down due to an active slide.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Minutes from home and they won''t let us into Olalla. There is an active rockslide. They''ve told us we have to go through Osoyoos. Not sure if we will g' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'et past Yellow Lake as there are also rocks coming down there, as well as just past Carter''s," Matson said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'ORIGINAL: 2:40 p.m.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Another landslide has been reported by DriveBC.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Just after 2:30 p.m. DriveBC shared that Highway 3A is closed in both directions due to a landslide between Main Street and Stagecoach Road for 6.0 km (12 to 6 km east of Keremeos).' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'A geo-technical assessment in progress.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'A detour is available via Highway 97 to Osoyoos then north on Highway 3.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'A rock slide has closed a road south of Okanagan Falls overnight.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Just after midnight, DriveBC reported the rock slide had fallen across Green Lake Road just south of the small South Okanagan community.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The slide is just south of the Okanagan Falls Provincial Park.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'There''s no indication at this time how long the closure is expected to last.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'These slides come just a few days after a landslide covered Highway 97 near Summerland. The highway is now opened to single-lane, alternating traffic. [pssg, embc, env, forr, tran]','DriveBC reports landslide Olalla and Keremeos ','Internet',1,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Madison Erhardt','Madison Erhardt',null,null,'SyndEnclosureImpl.length=75564' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/screen_shot_2023-05-21_at_2.37.41_pm_p3688499.jpg',0,60,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Penticton/427928/DriveBC-reports-landslide-Olalla-and-Keremeos',0,null,0,0,null,0,0,0,0,'astrating',0,0,0,null,0,0,0,0,null,null,null);
