Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778160778,to_date('18-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'Water restrictions have begun in Vernon.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Stage 1 restrictions were enacted Wednesday for all Greater Vernon Water customers, including residents of Vernon, Coldstream, and portions of Electoral Areas B, C and D, and Spallumcheen.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'GVW turned off its Kalamalka Lake water source May 5 due to poor water quality caused by high turbidity during freshet.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'It''s now experiencing challenges meeting demand because it is only using the Duteau water source and there has been higher-than-normal water use.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"While turning on the Kalamalka Lake water source, which is treated by the Mission Hill Water Treatment Plant, would alleviate the water supply issue, there is a risk that a water quality advisory would be required," GVW says.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Staff are keeping the Kalamalka Lake source off until turbidity levels are lower and stable.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Stage 1 restrictions aim to reduce water use by 10% or more.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Watering only twice a week or cutting back irrigation run times is encouraged. Watering is restricted to:' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '    Tuesday, Thursday, and/or Saturday if their property has an ODD ADDRESS NUMBER
