Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778508979,to_date('21-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'The City of Vernon paid $28,830,017 million in staff wages in 2022.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Staff also collected $44,637 in expenses last year.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'At their regular meeting Tuesday, administration will present a report on how much each employee and elected official made, plus how much was claimed in expenses in 2022.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Former city CAO Will Pearce was the highest paid employee at $255,132. Pearce also claimed just over $5,000 in expenses.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'For elected officials, Mayor Victor Cumming was the highest paid at $105,556 for the year.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The total remuneration for mayor and council for the year was $335,979.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Mayor and council also submitted $18,678 in expenses last year.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The city also paid out $166,657,957 for suppliers goods and services.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'To read the full report, click here. [maz]','City of Vernon lists wages for staff and council','Internet',1,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=135516' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/img_6550_p3557133_p3688281.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Vernon/427799/City-of-Vernon-lists-wages-for-staff-and-council',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778532730,to_date('21-MAY-23','DD-MON-RR'),'Global News: BC 1',to_date('01-JAN-70','DD-MON-RR'),'The Regional District of Okanagan Similkameen has started work to expand Wharf Park in Naramata''s electoral area ''E,'' which will continue until July.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The project is located along 1st Street, between Anna Avenue and 3rd Street. According to the RDOS, local traffic will be impacted during construction.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Alternative route signage will be in place at 4th Street and traffic control will be used as required.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The first phase of work is underway and will consist of the demolition of portions of 1st and 3rd streets.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The work will see 3rd Street realigned to meet B.C. Ministry of Transportation and Infrastructure standard, while the affected portion of 1st Street will be closed permanently.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The RDOS says this phase of the project will require the relocation of both overhead and subsurface utilities.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The second phase of this project is scheduled for fall 2023 and will include earthworks, turf, landscaping, fencing and irrigation system work.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Wharf Park was established at the site of an old Canadian Pacific Railway train dock and is one of three public beachfront parks in the community.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'In 2016, the RDOS acquired adjacent properties in order to expand Wharf Park.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'According to the RDOS, this project is intended to unify and upgrade these parcels of RDOS parkland. [maz, tran]','Work underway to expand Wharf Park in the South Okanagan','Internet',1,1,0,null,to_date('21-MAY-23','DD-MON-RR'),to_date('21-MAY-23','DD-MON-RR'),null,null,null,'column','Victoria Femia','Victoria Femia',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://globalnews.ca/news/9714333/work-expand-wharf-park-south-okanagan/',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
