Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778861020,to_date('23-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'A 57-year-old Mississauga, Ont., man accused of selling a lethal substance to people at risk of killing themselves has had his case put over until next week. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Peel Regional Police arrested Kenneth Law earlier this month and charged him with two counts of counselling or aiding suicide after investigating two recent deaths in the area. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Law appeared briefly in a Brampton, Ont., court on Tuesday, where his case was put over until May 30. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Law is accused of using several websites to market and sell sodium nitrite, a substance that is commonly used to cure meats but that can be deadly. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Peel Regional Police say their investigation has revealed at least 1,200 packages were allegedly sent to 40 countries. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Several police forces in Canada have said they are reviewing sudden deaths in their regions in light of the allegations against Law.','Kenneth Law case put over to next week following brief hearing','CP News',1,1,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.co