Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777298899,to_date('13-MAY-23','DD-MON-RR'),'CHAN',to_date('01-JAN-70','DD-MON-RR'),'Ravi Kahlon responds to the news that Shayne Ramsay has stepped down from Squamish Nation development company Nch''kay after the BC Housing audit found he violated conflict-of-interest rules. The Housing minister points out the forensic investigation highlighted real concerns, but he can''t speak to the decisions made by other organizations. [pdpe, zpz, hozz, tnf]','Kahlon - BC Housing audit','TV News',0,1,0,null,to_date('13-MAY-23','DD-MON-RR'),to_date('13-MAY-23','DD-MON-RR'),null,null,null,'column','Global BC Morning News','Global BC Morning News',null,null,null,126,240,null,to_date('01-JAN-70','DD-MON-RR'),'777298899.mp4','2023/05/13/777298899.mp4',null,0,'krypto',1,0,'video/quicktime',1,0,1,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777326557,to_date('13-MAY-23','DD-MON-RR'),'National Post',to_date('01-JAN-70','DD-MON-RR'),'Re: ''Safer supply'' fuelling a new opioid crisis -- Adam Zivo, May 9; and Poilievre lashes out at Liberals over drug policy -- Byran Passifiume, May 11' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The whole concept of giving "safe" drugs is unreasonable. Drug addiction is not a normal condition to be maintained. Drug addicts are generally dependent. They tend to harm themselves, and, sometimes, others. They are often involved in crime of some sort. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The solution to drug addiction is housing addicts where they cannot get drugs, and curing them of addiction. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Theodore Kass, MD, Victoria','''Safer supply'' failing','Newspaper',0,1,0,null,to_date('13-MAY-23','DD-MON-RR'),to_date('13-MAY-23','DD-MON-RR'),null,null,'A13','column','Theodore Kass','Theodore Kass',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,null,0,'krypto',0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
