Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777914439,to_date('17-MAY-23','DD-MON-RR'),'CBYG',to_date('01-JAN-70','DD-MON-RR'),'Marie Doduck is sharing her story of her arrival in Canada as a Jewish child survivor of World War Two. The Vancouver resident has written a memoir about her experience as a Holocaust survivor. The month of May is Canadian Jewish Heritage Month. [tacz]','Doduck - Holocaust survivor memoir','Talk Radio',0,1,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,null,'column','CBC Daybreak North','CBC Daybreak North',null,null,null,413,600,null,to_date('01-JAN-70','DD-MON-RR'),'777914439.m4a','2023/05/17/777914439.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'rfreeman',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777906735,to_date('17-MAY-23','DD-MON-RR'),'DailyHive',to_date('01-JAN-70','DD-MON-RR'),'Lululemon Athletica, a Vancouver-born global phenomenon of a brand, is hiring.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Positions vary regarding experience and education required, but most jobs pay well and come with great benefits and bonuses.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'While most positions are based in Vancouver, some are based in other parts of Metro Vancouver.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '  You might also like: - Disney is hiring in Vancouver and some of the salaries are magical - E-Comm is hiring in Vancouver offering good pay and a four-day workweek - 7 hot summer jobs that are in high demand in Vancouver and pay well' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'If you''ve got managerial experience, Lululemon is looking for an assistant manager in guest experience. Two openings based in Vancouver and Richmond pay up to $43 per hour. According to the job listing, assistant managers in guest experience are a crucial part of the store leadership team.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'All successful applicants need one year of people management experience and one year of leadership experience.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'For those with ambitions in design, Lululemon is also looking for a junior designer based out of Vancouver. According to Glassdoor, the position pays up to $96,000, and two to five years of industry experience are required, along with a BA, BFA, or BS in design.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Applicants also need proficiency in Adobe Illustrator, Photoshop, Excel, and Word and work with Mac computers.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'For those who gravitate more towards the tech side of things, Lululemon is also looking for a manager in digital brand experience operations.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Glassdoor states that this position''s typical hiring range in California is between $97,000 and $128,000 annually. Lululemon is looking for someone with around a decade of experience with an undergraduate degree in tech, business, marketing or a related field.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'If you have experience in retail, Lululemon is also seeking educators or retail sales associates. Positions pay up to $23.97 per hour, with highly sought-after perks, like discounts and yoga classes.','Lululemon is hiring in Vancouver and gigs pay as well as the pants fit','Internet',1,1,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,null,'column','Amir Ali','Amir Ali',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://dailyhive.com/vancouver/lululemon-hiring-vancouver-pay',0,null,0,0,null,0,0,0,0,'richard',0,0,0,null,0,0,0,0,null,null,null);
