Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (779299485,to_date('25-MAY-23','DD-MON-RR'),'CKNW',to_date('01-JAN-70','DD-MON-RR'),'Keith Baldrey reports at least two Surrey city councillors have signed non-disclosure agreements to gain access to the unredacted report generated by the province on the future of Surrey policing, noting Brenda Locke continues to refuse to do so. Global ''s legislative bureau chief also questions health authorities'' accountability in the wake of a statement by Surrey Memorial''s Dr Urbain Ip. Includes prior audio of David Eby, Adrian Dix and SPS chief Norm Lipinski. [zpz, pssg, hlth, maz]','Baldrey - Surrey policing/Surrey Memorial','Talk Radio',0,1,0,null,to_date('25-MAY-23','DD-MON-RR'),to_date('25-MAY-23','DD-MON-RR'),null,null,null,'column','CKNW Mike Smyth','CKNW Mike Smyth',null,null,null,0,600,null,to_date('01-JAN-70','DD-MON-RR'),'779299485.m4a','2023/05/25/779299485.m4a',null,0,'krypto',0,1,'video/quicktime',1,0,1,0,'tday',0,0,0,null,0,0,3,1685047712150,'Surrey policing','Issues','2023-05-25');
