Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777929345,to_date('17-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'TORONTO - Canadian teens will soon be able to hitch a ride with Uber as the ride-hailing app works to expand its market. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The American company used its global product showcase to announce it will begin allowing Canadians between the ages of 13 and 17 to make passenger accounts on the ride-hailing platform over the summer. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Teen accounts will first roll out in Western Canada and Quebec, followed by Ontario and Nova Scotia. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Uber''s current policy bans anyone under the age of 18 from holding an account, or using an account to call an Uber for someone under the age of 18 who plans to ride unaccompanied by an adult. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'But the company says with parents and children busier than ever, there was plenty of demand to create a way to let teens take Ubers. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Teen accounts will send parents and guardians notifications when teens request a ride, and will also allow the adults to track the trip and contact the driver or their child through Uber''s app. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '--- ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '(The Canadian Press) 
