Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778299434,to_date('19-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'The Nova Scotia government says the Health Department''s wait list for surgeries is shrinking. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The department has issued a statement saying surgical teams across the province completed thousands more operations and procedures last year than before the COVID-19 pandemic. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The statement says there were 1,873 more surgeries completed in the 2022-23 fiscal year than in 2019-20, and there were 4,863 more endoscopy and cystoscopy procedures completed last year than in 2019-20. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'As a result, the surgical wait list has been reduced by more than four-thousand people in the last year, though the department did not say how many people remain on the list. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Health Minister Michelle Thompson says the shrinking wait list can be attributed to improved scheduling of operating rooms, new acute-care beds and an expanded partnership with the Halifax Vision Centre for cataract surgeries. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'As well, Thompson says the number of outpatient hip and knee replacement surgeries increased to 1,193 in 2022-23, up from 85 in 2019-20. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Those patients returned home to recover rather than being admitted to hospital, leaving beds available for others, the department said. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Together, we are gaining ground and getting more Nova Scotians the surgeries and procedures they''ve been waiting for," Thompson said.  "We know there is more work to do to shorten surgical wait lists, but we are ready and willing to make the changes and investments needed to keep this momentum going."','Surgery wait list in Nova Scotia shrinking as procedures ramp up: Health Department','CP News',1,1,0,null,to_date('19-MAY-23','DD-MON-RR'),to_date('19-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2107581005/_k/y4BYB8amg5ElQ8uB',0,null,0,0,null,0,0,0,0,'chall',0,0,0,null,0,0,0,0,null,null,null);
