Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777929357,to_date('17-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'FORT MCPHERSON, N.W.T. _ A hamlet in the Northwest Territories'' Beaufort Delta region has declared a local state of emergency due to flooding from the Peel River. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Hamlet of Fort McPherson said Tuesday night that floodwaters had cut off access to the community''s airport and fresh water would be inaccessible in the near future. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Early today, it closed the road to a lake that provides the community''s water, as well as its solid waste facility. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Several public buildings in the community have been shut down to conserve water including Chief Julius School and the youth centre. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The territorial government says cabins on the banks of the river have flooded. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'It says subsequent water level rises will depend on how ice on the Peel River and Mackenzie River packs into the Mackenzie River Delta.','Fort McPherson, N.W.T., declares local state of emergency over flood ','CP News',1,1,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2107250884/_k/sKLuNZenuEaJRARO',0,null,0,0,null,0,0,0,0,'oscott',0,0,0,null,0,0,0,0,null,null,null);
