Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777628112,to_date('14-MAY-23','DD-MON-RR'),'Times Colonist (Victoria)',to_date('01-JAN-70','DD-MON-RR'),'Seattle rookie right-hander Bryce Miller shut down the Detroit Tigers for seven innings in a 5-0 victory Saturday that pushed the Mariners above .500 for the first time since they won on opening day. "Wow, Bryce Miller continues to roll," Mariners manager Scott Servais said. "I j','Mariners 5, Tigers 0','Newspaper',0,0,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),'Final','Scoreboard','B02','News',null,null,null,null,null,0,0,null,null,null,null,null,0,'VITC20230514163907.FMS',0,0,null,0,0,0,0,null,0,0,0,0,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778994379,to_date('24-MAY-23','DD-MON-RR'),'BiV',to_date('01-JAN-70','DD-MON-RR'),'The financial backers of a Vancouver-area online marketing firm are suing its founder over allegations stemming from a string of legal and financial headaches.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Paul Wong and Anne Wong first met Alfred Venegas in August 2020, according to the Wongs'' legal filings. Venegas reportedly told Paul Wong about his success using search engine optimization (SEO) to direct web traffic from people searching for personal protective equipment to the medical supplies company he was then working at.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'He allegedly told Paul Wong he''d recently been denied a raise and was looking for work elsewhere - and the two began talking regularly about starting a new marketing business. That business later became CT21 Analytics.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Paul Wong allegedly loaned Venegas $27,500 for equipment and software, and to cover the initial operating expenses. As the business grew, he later loaned Venegas money to rent office space and to hire more employees, according to the Wongs'' legal filings.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Paul Wong reportedly made 30 cash loans and seven Bitcoin loans over the course of 2021 and 2022, on top of forwarding loans from his own clients, for a total of $530,734. The Wongs also claim Venegas used money for his own rent for several months in 2021 and for two $2,600 computers.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Anne Wong claims she stepped in to help this business in May 2021, but Venegas allegedly refused her access to email and bank accounts - and when she did access the accounts in June 2021, the Wongs claim she still didn''t get administrative authority over the accounts.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'When Anne Wong accessed the company''s QuickBooks accounting software account in September 2021, she allegedly found Venegas hadn''t entered any expenses or receipts into the software.','B.C. marketing firm founder sued following string of financial headaches','Internet',1,1,0,null,to_date('24-MAY-23','DD-MON-RR'),to_date('24-MAY-23','DD-MON-RR'),null,null,null,'column','Dustin Godfrey','Dustin Godfrey',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://biv.com/article/2023/05/lawsuit-week-bc-marketing-firm-founder-sued-following-string-financial-headaches',0,null,0,0,null,0,0,0,0,'rfreeman',0,0,0,null,0,0,0,0,null,null,null);
