Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777608804,to_date('15-MAY-23','DD-MON-RR'),'CHAN',to_date('01-JAN-70','DD-MON-RR'),'Jay Sharpe says fire crews managed to contain a wildfire in Belcarra on Sunday. The Sasamat Fire chief notes the blaze could have been much worse. Meanwhile, BC Wildfire Service FIO Julia Caranci provides an update on the Shovelnose Creek wildfire, saying it''s burning out of control in difficult-to-reach terrain. [forr, embc, pssg]','Sharpe/Caranci - wildfire update','TV News',0,1,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),null,null,null,'column','Global BC Morning News','Global BC Morning News',null,null,null,185,240,null,to_date('01-JAN-70','DD-MON-RR'),'777608804.mp4','2023/05/15/777608804.mp4',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'oscott',0,0,0,null,0,0,0,0,null,null,null);
