Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778867555,to_date('23-MAY-23','DD-MON-RR'),'DailyHive',to_date('01-JAN-70','DD-MON-RR'),'Traffic in Fairview was snarled Tuesday morning after a crash left a car flipped on its side near Vancouver General Hospital.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Passerby Marcel Jepson saw the dark vehicle flipped on its side on 12th Avenue outside the BC Centre for Disease Control.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Traffic is moving slow," Jepson said on Twitter.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '> Car on its side on W 12th Ave (in front of the BCCDC) > Traffic is moving slow. #Vancouver #VancouverTraffic @CityNewsTraffic @AM730Traffic @TrafficVancity pic.twitter.com/lRZuMmEtuj >  > - Marcel Jepson (@Marcel_5_) May 23, 2023' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Daily Hive has reached out to the Vancouver Police Department for more details on what happened. There''s no word yet whether anyone was hurt.
