Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777335671,to_date('13-MAY-23','DD-MON-RR'),'Times Colonist (Victoria)',to_date('01-JAN-70','DD-MON-RR'),'West Shore RCMP arrested two youths for brandishing a weapon and making threats to passengers on a B.C. Transit bus this week.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police responded Wednesday at 8:15 p.m. to a report of a disturbance at the bus loop on Ocean Boulevard and Island Highway in Colwood involving two male youths.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'When confronted by another passenger, one of the youths brandished a baton and used it to threaten passengers, police said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Passengers on the bus did not report any physical injuries, police said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The youths were arrested for several offences, including possession of weapons for a dangerous purpose, uttering threats and breach of undertaking.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'RCMP said both were bound by conditions to not possess weapons and to not have contact with each other stemming from prior investigations.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'They were in court on Thursday, with one youth charged with possession of a weapon for dangerous purpose and two counts of breach of undertaking, and the other charged with one count of breach of undertaking.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Both youths have since been released by the court, police said.','Youths arrested after bus passengers threatened with weapon','Newspaper',0,1,0,null,to_date('13-MAY-23','DD-MON-RR'),to_date('13-MAY-23','DD-MON-RR'),null,null,'A04','column','Darron Kloster','Darron Kloster',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,null,0,'krypto',0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
