Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777335683,to_date('13-MAY-23','DD-MON-RR'),'Times Colonist (Victoria)',to_date('01-JAN-70','DD-MON-RR'),'It''s odd to see people rejoicing at Uber setting up shop in Victoria. I would have thought local business leaders would have been supporting local cab companies.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Instead they are the first to throw local cabbies under the bus.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'There is this idea that the public will now get discount cab service. But Uber has no magic vehicles. There are no economies of scale. Any saving comes off the back of the drivers.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The 25 per cent commission the drivers pay Uber leaves the community.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'That''s money no longer circulating in the stores and restaurants owned by the members of the Greater Victoria of Chamber of Commerce.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'It''s all about votes of course. The NDP likes to talk about "delivering rideshare."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'When I was in university, I spent a lot of time doing volunteer work for the NDP. As Corky Evans used to say, I liked their values.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'But they have screwed thousands of B.C. workers to privileged American rideshare companies.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'These are values we can do without.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Owen Brandon' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Victoria','Don''t be so happy to see Uber arrive here','Newspaper',0,1,0,null,to_date('13-MAY-23','DD-MON-RR'),to_date('13-MAY-23','DD-MON-RR'),null,null,'A10','column','Owen Brandon','Owen Brandon',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,null,0,'krypto',0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
