Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777360639,to_date('13-MAY-23','DD-MON-RR'),'CHEK',to_date('01-JAN-70','DD-MON-RR'),'Lana Popham is happy to report the Royal BC Museum''s Old Town exhibit will be reopening soon. The Tourism minister suggests the return of the popular exhibit will provide people with an opportunity to reflect on the complexity of history. RBCM CEO Alicia Dubois notes there are some changes to the exhibit, such as the theatre''s film selection. [tacz, zpz]','Popham/Dubois - Old Town exhibit','TV News',0,1,0,null,to_date('13-MAY-23','DD-MON-RR'),to_date('13-MAY-23','DD-MON-RR'),null,null,null,'column','CHEK News at Five','CHEK News at Five',null,null,null,150,240,null,to_date('01-JAN-70','DD-MON-RR'),'777360639.mp4','2023/05/13/777360639.mp4',null,0,'krypto',1,0,'video/quicktime',1,0,1,0,'astrating',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777366963,to_date('13-MAY-23','DD-MON-RR'),'CHAN',to_date('01-JAN-70','DD-MON-RR'),'The Regional District of the North Okanagan is warning residents about the dangers of BX Creek spilling its banks. Meanwhile, the Village of Cache Creek has issued a boil water advisory as crews continue to repair water infrastructure that was damaged in recent flooding. [env, forr, embc, pssg, hlth]','Flooding update','TV News',0,1,0,null,to_date('13-MAY-23','DD-MON-RR'),to_date('13-MAY-23','DD-MON-RR'),null,null,null,'column','Global BC News Hour','Global BC News Hour',null,null,null,63,180,null,to_date('01-JAN-70','DD-MON-RR'),'777366963.mp4','2023/05/13/777366963.mp4',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'astrating',0,0,0,null,0,0,0,0,'Flood season','Issues','2023-05-13');
