Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777628001,to_date('15-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'TORONTO - Grocery industry advocates say new rules to make companies pay to recycle packaging they put into the market in Ontario could simply shift costs from communities to consumers in the coming months. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'They say beverage companies have issued notices to retailers about a new container recycling fee on products ranging from milk and yogurt to juice and pop. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The fee, about three cents a bottle on average, was expected to take effect June 1. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'But an independent grocers'' group says the Canadian Beverage Container Recycling Association has now delayed passing the fee on to grocers _ which they say would raise retail prices _ until at least July 31. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Gary Sands, senior vice-president of the Canadian Federation of Independent Grocers, says beverage companies should be absorbing the costs themselves and not passing it on to consumers. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Still, he welcomes the delay given the ongoing high inflation on food in Canada. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '[env]','Ont Beverage Fees','CP News',0,0,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2106897031/_k/5vIxAPemYxHMalAb',0,null,0,0,null,0,0,0,0,'chall',0,0,0,null,0,0,0,0,null,null,null);
