Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778870204,to_date('23-MAY-23','DD-MON-RR'),'CKNW',to_date('01-JAN-70','DD-MON-RR'),'Jim Abram accuses BC Ferries of having outdated and ineffective IT services, noting the corporation itself has been complaining about it for years. The former Discovery Islands, Mainland Inlets director says its unacceptable that a critical part of BC''s highway infrastructure is completely unreliable. Bowen Island service cancellation and fare increases also discussed. With calls. [tran, bcff, tran]','Abram - BC Ferries travel chaos','Talk Radio',0,1,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,'column','CKNW Mike Smyth','CKNW Mike Smyth',null,null,null,932,900,null,to_date('01-JAN-70','DD-MON-RR'),'778870204.m4a','2023/05/23/778870204.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'tday',0,0,0,null,0,0,0,0,'BC Ferries cancellations','Issues','2023-05-23');
