Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777938447,to_date('17-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'Police say a man who escaped from a minimum-security unit at a federal prison in Kingston, Ont., has been found. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Ontario Provincial Police spokesperson Bill Dickson said the 42-year-old inmate was taken into custody without incident on Wednesday. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police had said earlier that prison staff discovered the inmate was missing during a formal count at the Collins Bay Institution on Tuesday. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The man was serving an indeterminate sentence for second-degree murder. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Dickson said the man has been charged with being unlawfully at large. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Correctional Service Canada said it will conduct an investigation into what happened.','Convicted murderer who escaped from federal prison in Kingston, Ont., located','CP News',0,0,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2107259761/_k/cIfSW3RLj9JWBGVN',0,null,0,0,null,0,0,0,0,'twells',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778870255,to_date('23-MAY-23','DD-MON-RR'),'DailyHive',to_date('01-JAN-70','DD-MON-RR'),'One person is in custody after allegedly firing shots at police officers in the Fraser Valley during an hours-long standoff.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Upper Fraser Valley detachment of the RCMP shared a release Tuesday morning detailing the incident. According to police, one man is in custody following a "high-risk police incident," which occurred on the 46000 block of Knight Road in Chilliwack.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Chilliwack RCMP were called to a residence at around 2:15 pm on Monday in response to a "distraught man who was reported to have access to multiple firearms."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Lower Mainland Integrated Emergency Response Team joined Chilliwack RCMP to attend the scene. Police say the man was "contained within a residence."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Later, at around 7:45 pm, police said that gunshots were allegedly fired toward police. At that point, residents in 16 homes in the area of Knight Road near Melville, Queens, and Downes were told to "shelter in place and stay away from external walls." They also asked the public to refrain from posting photos of police on social media.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '> Chilliwack RCMP are on scene at a high risk police incident involving shots fired. Residents in the area of Knight Rd near Melville, Queens and Downes are asked to shelter in place and stay away from external walls. Do not post photos of police on social media. More to follow >  > - Upper Fraser Valley RCMP (@UFVRD_RCMP) May 23, 2023' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Police say they engaged in efforts and negotiations to reach a peaceful resolution for the next few hours. Then, at around 12:30 am on Tuesday, the 29-year-old man was taken into police custody.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'During the incident, the "structure involved sustained significant fire damage," said police. A photo submitted to Daily Hive in the aftermath of the incident shows the charred remains of a structure on the scene.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Now, police will continue to investigate the incident and thank the residents of the area for their patients and cooperation.','Hours-long police standoff ends with man arrested, shots fired, house destroyed','Internet',1,1,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,'column','Sarah Anderson','Sarah Anderson',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://dailyhive.com/vancouver/police-standoff-arrested-shots-fired-house-destroyed',0,null,0,0,null,0,0,0,0,'lawrence',0,0,0,null,0,0,0,0,null,null,null);
