Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777387982,to_date('14-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'Shannon Friend-Yochim had another late-night visitor this week.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Crosby Road resident''s video system recorded a black bear as it wandered through the Bella Vista area.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"My backyard backs onto Davison Orchards, so I get lots of critters coming through here daily," Friend-Yochim said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The bear was spotted just after midnight on Tuesday.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"He walked around out back for awhile, then knocked over my composter which I''d forgotten to bring in. He pushed it about five feet - it''s a big one, and was mostly full of yard waste - then stole a compostable bag out of it, which he dragged to the back and ate what he wanted, then wandered away," she said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"We''ve had bobcats, deer, a Martin, coyotes, raccoons, marmots etc. Neighbours calls me ''Dr. Doolittle.'' I always inform neighbours when a bear comes around. This is the fourth bear we''ve seen in five years. Usually we only see him once. People up this way are pretty careful about garbage for the most part."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Friend-Yochim said there is also a cinnamon bear that is spotted once a year in the area. [env, forr]','Black bear spotted in Vernon neighbourhood earlier this week','Internet',1,1,0,null,to_date('14-MAY-23','DD-MON-RR'),to_date('14-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=134129' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/426453_0.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Vernon/426453/Black-bear-spotted-in-Vernon-neighbourhood-earlier-this-week',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
