Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778992392,to_date('24-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'CALGARY - Nearly 200 Calgary emergency doctors have released an open letter raising concerns about health care in Alberta. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The doctors say they have front-row seats to a major crisis. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'They say they are trying their best to provide care but are increasingly unable to do so. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The letter says there are signs of a capacity crisis everywhere as wait times to see a doctor reach 15 hours while patients get sicker as they wait. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The doctors say it''s common to have elderly patients on stretchers in hallways and patients with mental health crises housed in the emergency room awaiting in-patient beds. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'They say the pandemic damaged health care, but the further erosion is a combination of the pandemic''s aftermath and untimely government policy. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'They say they hope whoever forms government addresses the issues immediately. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '---','BR Alta Elxn Health','CP News',0,0,0,null,to_date('24-MAY-23','DD-MON-RR'),to_date('24-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-J