Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777937283,to_date('17-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'OTTAWA - Experts say a Liberal bail reform bill introduced this week could be subject to a Charter challenge and see limited results. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The bill aims to make it harder for some repeat violent offenders to seek pretrial release, by putting the onus on them to prove why they should be granted bail. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Danardo Jones, an assistant professor at the University of Windsor''s law school, says he isn''t sure the bill would pass constitutional muster. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Jones says the Supreme Court has cautioned governments before on any expansion of what are known as reverse onus measures. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Charter of Rights and Freedoms guarantees that anyone who is charged with a crime will not be denied reasonable bail without just cause. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Queen''s University sociologist Nicole Myers says the impact of the new law could be "limited" because the measures don''t address the root causes of crime. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '[mjag, pssg]','Bail Reform','CP News',0,0,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2107258689/_k/BVb7DemyiH4v4Jqe',0,null,0,0,null,0,0,0,0,'twells',0,0,0,null,0,0,0,0,null,null,null);
