Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777387983,to_date('14-MAY-23','DD-MON-RR'),'Castanet',to_date('01-JAN-70','DD-MON-RR'),'Kamloops city council voted unanimously to adopt a new code of conduct during a meeting on Tuesday.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The code of conduct sets out expectations for elected officials or committee members, which would include citizens, should they be appointed to committees in the future.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The code outlines that these individuals must not bully or harass others, and must treat other members, city staff and city volunteers with respect.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Council and committee members must avoid making statements attacking other members, staff or volunteers or their respective families, and must not obstruct city staff in their efforts to implement council decisions.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'While introducing the new code of conduct in a mid-April meeting, Maria Mazzotta, the city''s corporate officer, said the bylaw includes consequences if the code of conduct is breached, and there is a "clear and fair process" leading to the imposition of these consequences.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'During the meeting last month, council also approved a motion put forward by Coun. Nancy Bepple to review the code of conduct bylaw again next year. [maz]','Kamloops council votes unanimously to officially adopt new code of conduct','Internet',1,1,0,null,to_date('14-MAY-23','DD-MON-RR'),to_date('14-MAY-23','DD-MON-RR'),null,null,null,'column','Castanet','Castanet',null,null,'SyndEnclosureImpl.length=110695' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.interface=interface com.sun.syndication.feed.synd.SyndEnclosure' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.type=image/jpeg' || CHR(13) || CHR(10) || 'SyndEnclosureImpl.url=https://www.castanet.net/content/2023/5/city_hall_summer_-_kh_p3685748.jpg',0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://www.castanet.net/news/Kamloops/426472/Kamloops-council-votes-unanimously-to-officially-adopt-new-code-of-conduct',0,null,0,0,null,0,0,0,0,'calmazan',0,0,0,null,0,0,0,0,null,null,null);
