Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777628071,to_date('14-MAY-23','DD-MON-RR'),'The Province',to_date('01-JAN-70','DD-MON-RR'),'In 2020, Vivek Shraya debuted a new theatrical work titled How to Fail as a Popstar. Three years later, the Calgary-based transgender singer releases Baby, You''re Projecting, on Vancouver- based label MINT Records.  Declaring the whole pop star thing kaput was a tad pre-emptive.','''I might never be done with music''; Latest release suggests Shraya hasn''t finished pursuing pop stardom quite yet','Newspaper',0,0,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),'Final','Entertainment','A36',null,null,'Stuart Derdeyn',null,null,null,0,0,null,null,null,null,null,0,'VAPR20230514163907.FMS',0,0,null,0,0,0,0,null,0,0,0,0,0,0,0,0,null,null,null);
