Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778310164,to_date('19-MAY-23','DD-MON-RR'),'iNFOnews',to_date('01-JAN-70','DD-MON-RR'),'At least one wildfire started in the Shuswap after last night''s lightning storm. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '  The fire was discovered this morning, May 19, near Aline Hill, according to fire information officer Melanie Bibeau with B.C. Wildfire Service. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '   ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '  Bibeau said three crew members and one helicopter were assigned to it, and that the size of the fire has not yet been recorded. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '  Additionally, another helicopter has been deployed to survey areas most impacted by last night''s storm. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '  More information on the Aline Hill wildfire is expected later today, and details will become available if other lightning-caused wildfires get discovered,&nbsp;Bibeau said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '  To contact a reporter for this story, email Dan Walton&nbsp;or call 250-488-3065 or email the editor. You can also submit photos, videos or news tips to the newsroom&nbsp;and be entered to win a monthly prize draw. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '  We welcome your comments and opinions on our stories but play nice. We won&#39;t censor or delete comments unless they contain off-topic statements or links, unnecessary vulgarity, false facts, spam or obviously fake profiles. If you have any concerns about what you see in comments, email the editor in the link above.&nbsp;','One wildfire discovered in the Shuswap after lightning storm','Internet',1,1,0,null,to_date('19-MAY-23','DD-MON-RR'),to_date('19-MAY-23','DD-MON-RR'),null,null,null,'column','Dan Walton','Dan Walton',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://infotel.ca/newsitem/one-wildfire-discovered-in-the-shuswap-after-lightning-storm/it98430',0,null,0,0,null,0,0,0,0,'richard',0,0,0,null,0,0,0,0,null,null,null);
