Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778995798,to_date('24-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'The Nunavut government is ending a week-long state of emergency in Kinngait as water services resume in the hamlet. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The territory declared the state of emergency last Wednesday saying an electrical issue at the community''s water pumphouse was limiting its ability to distribute treated water. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'It said available reserve volumes had been depleted, posing a risk to public health and community infrastructure. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Minister of Community and Government Services David Joanasie says those issues have now been addressed and municipal services have been restored in Kinngait. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The state of emergency ended at midnight. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The hamlet on Baffin Island was formerly known as Cape Dorset until 2020 and is home to around 1,400 people.','Nunavut ends state of emergency as water services restored in Kinngait ','CP News',1,1,0,null,to_date('24-MAY-23','DD-MON-RR'),to_date('24-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2108450165/_k/fB2t07qhW9425Xn4',0,null,0,0,null,0,0,0,0,'chall',0,0,0,null,0,0,0,0,null,null,null);
