Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777942476,to_date('17-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'A report on Prince Edward Island''s ailing health-care system says the province needs about 1,200 additional workers over the next 10 years. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The report by Halifax-based health-care consulting firm Health Intelligence says the province will need 1,194 more workers across all health disciplines by 2032. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Health Intelligence says its forecast is based on the province''s plan to reform the health-system by adding more nurses, doctors and pharmacists to the network. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'It says the province would only need 245 more health workers over the same period should the government implement a less ambitious reform. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The consulting firm says its report takes into account things such as retirement, migration out of province, and the death rate of workers. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The report says much of the health burden in the province is caused by cancer, cardiovascular disease, chronic pulmonary disease, and diabetes.','Prince Edward Island will need about 1,200 more health workers by 2032: forecast','CP News',1,1,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2107261923/_k/JQhP0Lh0Zeg6bgoI',0,null,0,0,null,0,0,0,0,'chall',0,0,0,null,0,0,0,0,null,null,null);
