Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778179289,to_date('18-MAY-23','DD-MON-RR'),'DailyHive',to_date('01-JAN-70','DD-MON-RR'),'How would you react if you found out you were suddenly half a million dollars richer?' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Would you cry out with glee? Would you start shaking or pacing?' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'When Jeffrey Scott of Langley, BC, found out that he and his wife, Mari Volkaert, had won $500,000 from Lotto 6/49, he immediately froze.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Scott was at home relaxing on the couch when checked the ticket using the BCLC Lotto! app.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Metro Vancouver residents bought the ticket from the On the Run in Aldergrove, on Fraser Highway and 264 Street.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'After recovering from their own initial shock, Scott and Volkaert shared the news with family, though they "didn''t believe us at first," he said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The couple shared that they enjoy spending time with family and working around their house, especially in the yard. They have no specific plans on how to spend their jackpot, but Scott and Volkaert added that "it will make our life easier, that''s for sure." [mjag]','Family left in disbelief from lotto couple''s huge jackpot win','Internet',1,1,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,'column','Daniel Chai','Daniel Chai',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://dailyhive.com/vancouver/lottery-winner-jeffrey-scott-mari-volkaert',0,null,0,0,null,0,0,0,0,'twells',0,0,0,null,0,0,0,0,null,null,null);
