Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777628051,to_date('14-MAY-23','DD-MON-RR'),'The Province',to_date('01-JAN-70','DD-MON-RR'),'A high-ranking Port Moody police officer is suing two RCMP dog handlers after he was tackled by one of them and bitten by a police dog next to his Surrey home as they pursued a suspect, despite him repeatedly yelling "it wasn''t me, it wasn''t me."  Inspector Manjinder Singh Kaila,','RCMP officers tackle, then sic dog on homeowner, also a cop; now he''s suing; Port Moody inspector says he''s suffered chronic pain and public humiliation','Newspaper',0,0,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),'Final','News','A03',null,null,'Susan Lazaruk',null,null,null,0,0,null,null,null,null,null,0,'VAPR20230514163907.FMS',0,0,null,0,0,0,0,null,0,0,0,0,0,0,0,0,null,null,null);
