Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778857028,to_date('23-MAY-23','DD-MON-RR'),'CBU',to_date('01-JAN-70','DD-MON-RR'),'Violette Baillargeon and Kristie Oxley are concerned with the lack of air conditioning in Surrey and New Westminster schools. The former teacher and the president of the New Westminster Teachers'' Union warns is it especially uncomfortable in portables during heat waves. [edu, hlth, lbrr]','Oxley/Baillargeon - school heat concerns','Talk Radio',0,1,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,'column','CBC Early Edition','CBC Early Edition',null,null,null,509,420,null,to_date('01-JAN-70','DD-MON-RR'),'778857028.m4a','2023/05/23/778857028.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'lgranberg',0,0,0,null,0,0,0,0,null,null,null);
