Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778872489,to_date('23-MAY-23','DD-MON-RR'),'CP News',to_date('01-JAN-70','DD-MON-RR'),'WINNIPEG _ The Manitoba government is putting up new money to support Pride events and services for the LGBTQ community. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Premier Heather Stefanson says Pride Winnipeg is to receive annual grants of $250,000, which allows the organization to hire staff and offer year-round programming. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Progressive Conservative government is also putting up $490,000 over two years to help decrease wait lists for people requiring gender-affirming care and surgical procedures. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Stefanson ran afoul of Pride Winnipeg last year when she spoke at the annual Pride rally but did not walk in the parade. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Pride Winnipeg says Stefanson is still under a one-yearban from speaking at the rally but is welcome to march in the parade this year. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Stefanson says she will walk in the parade and Families Minister Rochelle Squires will speak on behalf of the government. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'This report by The Canadian Press was first published May 23, 2023.','Manitoba increases funding for Winnipeg Pride, Premier Stefanson to walk in parade','CP News',1,1,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'http://www.commandnews.com/fpweb/fp.dll/$bc-rss/htm/rss/x_dv.htm/_ibyx/daj/_svc/cp_pub/_Id/2108284561/_k/jD8MRtpw9UOD3kyV',0,null,0,0,null,0,0,0,0,'rdrain',0,0,0,null,0,0,0,0,null,null,null);
