Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777628057,to_date('14-MAY-23','DD-MON-RR'),'The Province',to_date('01-JAN-70','DD-MON-RR'),'As if leading his team to the Super Bowl and signing a massive contract extension weren''t enough, Philadelphia Eagles quarterback Jalen Hurts decided to add to his stellar year by earning a master''s degree.  Hurts, 24, received his master''s in human relations from Oklahoma on Fri','Eagles QB Hurts earns master''s degree; Football; Sportsticker','Newspaper',0,0,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),'Final','Sports','A52',null,null,null,null,null,null,0,0,null,null,null,null,null,0,'VAPR20230514163907.FMS',0,0,null,0,0,0,0,null,0,0,0,0,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778872491,to_date('23-MAY-23','DD-MON-RR'),'DailyHive',to_date('01-JAN-70','DD-MON-RR'),'A last-minute lottery ticket has paid off in a big win for Canada''s latest millionaire.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Sun Jie of Richmond, BC, was at the pharmacy when she decided to buy a Lotto 6/49 ticket for the May 10, 2023, draw.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Jie checked her ticket using a self-scanner in Admiralty Centre and was shocked when the numbers popped up on the screen in front of her. Her family felt the same way when they heard the good news.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"My family couldn''t believe I won that kind of money," Jie shared. "They thought it was unbelievable."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The Metro Vancouver resident bought the winning ticket at the Real Canadian Superstore on No. 3 Road.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Jie said that she is taking some time to decide what to do with her winnings, but added that she plans to treat her family to a nice trip. Japan is one destination she is considering soaring off to.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'And the fact that she is now a millionaire is still sinking in.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Surprised," when asked how it feels to win the big prize. "I believe anything is possible." [fin, bclc]','"Anything is possible": Lotto winner soaring high after scoring big jackpot','Internet',1,1,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,'column','Daniel Chai','Daniel Chai',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://dailyhive.com/vancouver/lottery-winner-sun-jie',0,null,0,0,null,0,0,0,0,'lawrence',0,0,0,null,0,0,0,0,null,null,null);
