Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777925422,to_date('17-MAY-23','DD-MON-RR'),'Ming Pao News',to_date('01-JAN-70','DD-MON-RR'),'The inflation rate in Canada climbed 4.4% in April and the cost of groceries even climbed 9.1%. The general public complain that the cost of living has significantly increased but their salary increase cannot catch up.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Richmond resident Ms. Tsang told Ming Pao Daily that her salary only increased by $200 in the last two years and it won''t be able to catch up with the increase of cost of living. She says when she goes grocery shopping, she only buys products that are on sale. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'She says in the past, she and her husband would spend about $600 to $800 a month dining out on weekends. In order to save money, they now dine out once a week and keep the spending within $300 a month. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Burnaby resident Ms. Cheung said the increase of cooked food prices in supermarkets is significant. She recalled that a portion of cooked food cost only $4 to $5 a year ago but it''s now costs more than $8. She said as an ordinary resident, she can no longer spend recklessly and buy whatever she wants. She also said the costs of dining out have increased a lot. In a Szechuan restaurant in Richmond, the price of a dish of spicy shrimps has increased from $29 to $33, and in some hot pot restaurant, the salad bar now costs $3 per person instead of being provided for free, she said. [fin, zhx]','Residents buy special priced products, reduce dining out ','Internet',1,1,0,null,to_date('17-MAY-23','DD-MON-RR'),to_date('17-MAY-23','DD-MON-RR'),null,null,'A01',null,null,null,null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,null,0,'krypto',0,0,null,0,0,0,0,'cdan',0,0,0,null,0,0,0,0,null,null,null);
