Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778862897,to_date('23-MAY-23','DD-MON-RR'),'CBYG',to_date('01-JAN-70','DD-MON-RR'),'John Vaillant explains what he learned from Fort McMurray''s wildfires in 2016, the costliest disaster in Canadian history. The Fire Weather author is hopeful the turn from fossil fuels to greener energy can help as western Canada deals with hotter, more destructive wildfires every year. [forr, embc, pssg, empr, env]','Vaillant - Fort McMurray wildfire lessons','Talk Radio',0,1,0,null,to_date('23-MAY-23','DD-MON-RR'),to_date('23-MAY-23','DD-MON-RR'),null,null,null,'column','CBC Daybreak North','CBC Daybreak North',null,null,null,340,600,null,to_date('01-JAN-70','DD-MON-RR'),'778862897.m4a','2023/05/23/778862897.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'rfreeman',0,0,0,null,0,0,0,0,null,null,null);
