Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (777627649,to_date('15-MAY-23','DD-MON-RR'),'DailyHive',to_date('01-JAN-70','DD-MON-RR'),'A wildfire broke out near Squamish over the weekend, and it''s now burning out of control.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'BC Wildfire Service has named the blaze the Shovelnose Creek fire, and it''s estimated to be 17 hectares in size (0.17 square kilometres).' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The fire was discovered Saturday afternoon about 20 kilometres up the Squamish Valley Forest Service Road.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"This fire is burning in steep, rugged, challenging terrain," the BC Wildfire Service said in a tweet. "Crews responded into the night and will be supported by helicopters during the day."' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '> #BCWildfire is continuing to respond to the Shovelnose Creek fire (V30293), located at the 20 km mark along Squamish River FSR, west of the communities #Squamish and #Pemberton. pic.twitter.com/jnsbgXrjmd >  > - BC Wildfire Service (@BCGovFireInfo) May 14, 2023' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Roger Diamond Lewis saw the fire and shared images of it on social media. A helicopter is seen dropping what appears to be flame retardant.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || ' The BC Wildfire Service says no homes or infrastructure are currently at risk. The fire is suspected to be human-caused, and the Wildfire Service advised those using forest services roads for recreation to use caution when doing any activity that could start a fire.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || '"Please avoid areas where there are active wildfires burning for the safety of yourself and first responders," it said.' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || ' [env, forr, embc, pssg]','Out-of-control wildfire sparked over the weekend near Squamish','Internet',1,1,0,null,to_date('15-MAY-23','DD-MON-RR'),to_date('15-MAY-23','DD-MON-RR'),null,null,null,'column','Megan Devlin','Megan Devlin',null,null,null,0,0,null,to_date('01-JAN-70','DD-MON-RR'),null,null,'https://dailyhive.com/vancouver/out-of-control-wildfire-near-squamish',0,null,0,0,null,0,0,0,0,'twells',0,0,0,null,0,0,0,0,null,null,null);
