Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778169172,to_date('18-MAY-23','DD-MON-RR'),'CBYK',to_date('01-JAN-70','DD-MON-RR'),'Ken Uzeloc sent several crew members and a bush truck to assist in fighting wildfires near Fort St John. Kamloops Fire Rescue''s fire chief is also concerned by the increase in suspicious fires in Kamloops. [pssg, env, forr, embc]','Uzeloc - BC wildfires & Kamloops fires','Talk Radio',0,1,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,'column','CBC Daybreak Kamloops','CBC Daybreak Kamloops',null,null,null,501,540,null,to_date('01-JAN-70','DD-MON-RR'),'778169172.m4a','2023/05/18/778169172.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'jglass',0,0,0,null,0,0,0,0,null,null,null);
Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (778170255,to_date('18-MAY-23','DD-MON-RR'),'CBU',to_date('01-JAN-70','DD-MON-RR'),'Leanne Kopp has mixed feelings about BC''s decision to send cancer patients to Bellingham, Washington for radiation treatment. The Island Prostrate Centre executive director thinks having to travel across the border will add a whole new level of stress for patients, but she notes it will allow some patients to receive treatment sooner. Sonia Furstenau agrees the plan will put additional stress on patients who must travel. The Green Party leader finds it unfortunate that BC is in a position that it has to do this. [hlth, pdpe, zpz]','Kopp/Furstenau - US cancer treatment BC ','Talk Radio',0,1,0,null,to_date('18-MAY-23','DD-MON-RR'),to_date('18-MAY-23','DD-MON-RR'),null,null,null,'column','CBC Early Edition','CBC Early Edition',null,null,null,641,720,null,to_date('01-JAN-70','DD-MON-RR'),'778170255.m4a','2023/05/18/778170255.m4a',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'oscott',0,0,0,null,0,0,0,0,null,null,null);
