Insert into TNO.NEWS_ITEMS (RSN,ITEM_DATE,SOURCE,ITEM_TIME,SUMMARY,TITLE,TYPE,FRONTPAGESTORY,PUBLISHED,ARCHIVED,ARCHIVED_TO,RECORD_CREATED,RECORD_MODIFIED,STRING1,STRING2,STRING3,STRING4,STRING5,STRING6,STRING7,STRING8,STRING9,NUMBER1,NUMBER2,DATE1,DATE2,FILENAME,FULLFILEPATH,WEBPATH,THISJUSTIN,IMPORTEDFROM,EXPIRE_RULE,COMMENTARY,CONTENTTYPE,BINARYLOADED,LOADBINARY,EXTERNALBINARY,CBRA_NONQSM,POSTEDBY,ONTICKER,WAPTOPSTORY,ALERT,AUTO_TONE,CATEGORIES_LOCKED,CORE_ALERT,COMMENTARY_TIMEOUT,COMMENTARY_EXPIRE_TIME,EOD_CATEGORY,EOD_CATEGORY_GROUP,EOD_DATE) values (779305640,to_date('24-MAY-23','DD-MON-RR'),'CHNM',to_date('01-JAN-70','DD-MON-RR'),'The Surrey Police Service is issuing an open letter today claiming the delays in transition away from the RCMP to a municipal policing force are having an impact on policing in the city. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'SPS Chief Constable Norm Lipinski has spoken publicly, saying that the province has come out with its recommendation to continue the policing transition but his force is going through an uncertainty due to the lack of clarity in this matter. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'The letter is addressed to the city council and residents of Surrey. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'Premier David Eby hopes that the city council will make a decision on this matter very soon, saying government is making sure the back and forth does not affect the delivery of police services in Surrey. ' || CHR(13) || CHR(10) || CHR(13) || CHR(10) || 'This is not a decision that will only affect that city -- this is a decision with far greater effects than that as the report shows, Eby adds. [zhj, pssg, maz, pdpe, zpz]','Lipinski/Eby - Surrey policing','TV News',0,1,0,null,to_date('25-MAY-23','DD-MON-RR'),to_date('25-MAY-23','DD-MON-RR'),null,null,null,'column','OMNI Punjabi News','OMNI Punjabi News',null,null,null,0,1500,null,to_date('01-JAN-70','DD-MON-RR'),'779305640.mp4','2023/05/24/779305640.mp4',null,0,'krypto',0,0,'video/quicktime',1,0,1,0,'asidhu',0,0,0,null,0,0,0,0,'Surrey policing','Issues','2023-05-25');
